import { FilterPanelSettings, IFilterPanel } from "./filterpanel.model";
import { DialogsService, LongWorkService } from "../../providers/uikit.dialogs";
import { FilterPanel, FilterPanelRepository } from "./filterpanel";
import { BehaviorSubject } from "approot/global/models/common.reactive";

class FilterPanelController {
	public filterPanel: IFilterPanel | BehaviorSubject<IFilterPanel>;

	public fpSettings: FilterPanelSettings;
	private filterPanelRepository: FilterPanelRepository;

	/*@ngInject*/
	constructor(
		private $scope: ng.IScope,
		private $element: JQuery<HTMLElement>,
		$http: ng.IHttpService,
		private $longWork: LongWorkService,
		private $dialogs: DialogsService) {
		this.$element.addClass("filters-panel")
		this.$element.css("display", "block");
		this.filterPanelRepository = new FilterPanelRepository($http, $dialogs, $longWork)
	}

	$onInit() {
		if (!this.fpSettings.styles || this.fpSettings.styles.compact) {
			this.$element.addClass("filters-panel-compact");
		}

		if (!this.fpSettings.info && !this.fpSettings.sources && this.fpSettings.url) {
			this.filterPanelRepository.getFpInfo(this.fpSettings.url)
				.then((preparedFp) => {

					this.fpSettings.info = preparedFp.filterPanel;
					this.fpSettings.sources = preparedFp.filterSources;

					this.init();
				});

			return;
		}

		this.init();
	}


	init() {
		let initFiltersUrl = this.fpSettings.initUrl || this.fpSettings.url;

		let filterPanel = new FilterPanel(this.$longWork, this.$dialogs, this.filterPanelRepository, this.$element, this.fpSettings.info, this.fpSettings.sources, initFiltersUrl, true, null, this.fpSettings.styles);
		if (this.fpSettings.events && this.fpSettings.events.ready) {
			filterPanel.ready(this.fpSettings.events.ready);
		}

		if (this.fpSettings.events && this.fpSettings.events.canChange) {
			filterPanel.canChange = this.fpSettings.events.canChange;
		}

		if (this.fpSettings.events && this.fpSettings.events.emptyChoice) {
			filterPanel.emptyChoice(this.fpSettings.events.emptyChoice);
		}

		if (this.filterPanel && (<any>this.filterPanel).next) {
			(<BehaviorSubject<IFilterPanel>>this.filterPanel).next(filterPanel);
		}
		else {
			this.filterPanel = filterPanel;
		}

		if (this.fpSettings.values) {
			this.setValues()
		}

		this.$scope.$applyAsync(() => {
			filterPanel.initPanel();
		});
	}

	private setValues(){
		let sources = this.fpSettings.sources;
		for (const filterId in this.fpSettings.values) {
			const value = this.fpSettings.values[filterId];
			let source = sources.find(s => s.filterId == filterId);
			if (!source) {
				continue;
			}
			source.defaultValue = value;
		}
	}
}

export const FilterPanelComponent = {
	bindings: {
		filterPanel: "=?fp",
		fpSettings: "=fpSettings",
	},
	selector: "filterPanel",
	controller: FilterPanelController
}


