let selectedOrganizationsViewController = ($scope) => {
    $scope.language = language;
    let $ctrl = $scope.$ctrl;
    $scope.model = {};
    //$ctrl.$setViewValue($scope.model);

    $scope.$watch("$ctrl.model", () => {
        if (!$ctrl.model || !$ctrl.model.selectedIds) return;

        $scope.model = $ctrl.model;

        $scope.groups = [
            {
                name: `${language.Generic.EMReports.kTotal} ${language.Generic.Calendar.kSelected.toLowerCase()} ${$scope.model.selectedIds.length}`,
                schoolsIds: $scope.model.selectedIds,
                level: null,
                updateMethod: $ctrl.model.updateMethod,
                editModel: $ctrl.model.editModel
            }
        ];

        let getName = (object) => !!object ? object.name : "";

        for (let index in $scope.model.selectedLevels) {
            let level = $scope.model.selectedLevels[index];

            let schoolsIds = $scope.model.selectedOrgs
                .filter(school => !level.municipalityDistrict || school.provinceLevel.id == Math.abs(level.municipalityDistrict.id))
                .filter(school => !level.city || school.cityLevel.id == level.city.id)
                .filter(school => !level.funcType || school.funcTypeLevel.id == level.funcType.id)
                .map(school => school.id);

            // Заглушка плавающей ошибки выделения элементов дерева
            if (schoolsIds.length === 0) continue;

            let trimer = /^[,\s]*(.*?)[,\s]*$/; //срезать пробелы и ',' в начале и конце строки
            let levelName = trimer.exec(`${getName(level.municipalityDistrict)}, ${getName(level.city)}, ${getName(level.funcType)}`)[1];
            let selectedOrgsCount = `${language.Generic.Calendar.kSelected.toLowerCase()} ${schoolsIds.length}`;

            let result = {
                name: `${levelName} ${selectedOrgsCount}`,
                level: level,
                schoolsIds: schoolsIds,
                updateMethod: $ctrl.model.updateMethod,
                editModel: $ctrl.model.editModel
            }

            $scope.groups.push(result);
        }
    });

    $scope.showAll = false;
    $scope.chunkShow = (count) => !$scope.showAll && count
        ? (element, index) => count > index
        : () => true;

    $scope.showAllClick = () => $scope.showAll = !$scope.showAll;

    $scope.filterGroups = (element, index, allElements) => {
        let elements = allElements
            .filter(o => o.schoolsIds.length == element.schoolsIds.length)

        let singleCompareA = (levelA, levelB, method) => {
            let a = method(levelA);
            let b = method(levelB);
            if (!a && b) return false;
            return true;
        }

        let compareA = (levelA, levelB, methods) => {
            for (let index in methods) {
                if (!singleCompareA(levelA, levelB, methods[index]))
                    return false;
            }

            return true;
        }

        let level = element.level;
        for (let index in elements) {
            let currentLevel = elements[index].level;
            if (currentLevel == null) continue;
            if (level == null) return false;
            if (!compareA(level, currentLevel, [(o) => o.municipalityDistrict, (o) => o.city, (o) => o.funcType])) {
                return false;
            }
        }
        return true;
    }
}

let selectedOrganizationsViewComponent = {
    templateUrl: '/static/dist/app/global/ui-components/selectedOrganizationsView/template.html',
    controller: selectedOrganizationsViewController,
    bindings: {
        model: '='
    }
}

let rowController = ($scope, modalSelectOrganizations) => {
    $scope.language = language;
    let $ctrl = $scope.$ctrl;

    $ctrl.$onInit = () => {
        $scope.model = $ctrl.model;
    }

    $scope.click = () => {
        let showModel = {
            selected: $ctrl.model.schoolsIds,
            updateMethod: $ctrl.model.updateMethod,
            editModel: $ctrl.model.editModel
        }
        modalSelectOrganizations.showOrgs(showModel);
    }
}

let rowViewComponent = {
    templateUrl: '/static/dist/app/global/ui-components/selectedOrganizationsView/rowTemplate.html',
    controller: rowController,
    bindings: {
        model: '='
    }
}

const moduleNamespace = 'irtech.netcity.ui-components';
const moduleName = 'selectedOrganizationsView';

angular.module(moduleNamespace)
    .component(moduleName, selectedOrganizationsViewComponent)
    .component(`${moduleName}Row`, rowViewComponent);


