"use strict";

import { UnderscoreStatic } from "underscore";
import { IFilterPanel, FilterPanelSettings, FilterSource } from "../filterpanel/filterpanel.model";
import { DependencyTracker } from "../filterpanel/dependencyTracker";
import { BehaviorSubject } from "approot/global/models/common.reactive";
import MultiSelectable from "approot/global/multiSelectable";
import { LongWorkService, DialogsService } from "approot/global/providers/uikit.dialogs";
import { AppLoader } from "approot/global/apploader";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import { RegistryInfo, RegistryBtn, Decorator, SelectionMode, IRegistryController, RegistryFieldInfo, RegistryDescription, RegistryResponse, RegistryPagingInfo, RegistryState, RegistryRequest, RegistryCommandInfo, IRegistryControllerState } from "./registry.model";
import { RegistryRepository } from "./registry.repository";

declare var $: any;
declare var _: UnderscoreStatic;
declare var angular: ng.IAngularStatic;
declare var extDeferred: any;

interface RegistryFieldViewInfo extends RegistryFieldInfo {
	sortOrder?: OrderDirection;
	decorator: Decorator;
}

interface RegistryFieldChooseModel {
	id: string;
	title: string;
	selected: boolean;
	oneCheckedOnly: (checked: any) => boolean;
}

export enum OrderDirection {
	"asc" = "asc",
	"desc" = "desc"
}

//умолчательные настройки
const defRegistryInfo: RegistryInfo = {
	url: null,
	filtersUrl: null,
	buttons: null,
	linkButtons: null,
	fieldDecorators: null,
	extensions: {
		postButtonsTpl: null
	},
	filterPanelStyles: {
		compact: true,
		label: "col-md-4 col-lg-5 col-sm-4",
		control: "col-md-8 col-lg-6 col-sm-8",
	},
	registryStyles: {
		table: "table-xs table-bright table-bright-hover table-thin",
		filtersForm: "form-sm"
	},
	//compactFilters: true,
	initialPageSize: 50,
	export: true,
	filtersValues: null
};

let scrollable = false;

class RegistryFieldsHelper {
	constructor(private registryCtrl: RegistryController) {
	}

	initAvailableFields(): RegistryFieldInfo[] {
		let fp = this.registryCtrl.filterInfo.filterPanel.getValue();
		const filterValues = fp.getValues();

		const availableFields = this.registryCtrl.data.registry.fields
			.filter((field) => {
				if (!field.dependencies) {
					return true;
				}
				return new DependencyTracker(field.dependencies).isSatisfied(filterValues);
			});

		return availableFields;
	}

	initDisplayFilters() {
		//инициализация полей реестра
		let fields = <RegistryFieldViewInfo[]>this.initAvailableFields();

		if (this.registryCtrl.data.registryData) {
			fields = fields.filter((f) => this.registryCtrl.data.registryData.fields.indexOf(f.id) > -1);
		}

		if (this.registryCtrl.registry.fieldDecorators) {
			fields.forEach(f => f.decorator = this.registryCtrl.registry.fieldDecorators[f.id])
		}
		this.registryCtrl.data.displayFields = _.sortBy(fields, (f) => f.order);
	}
}

export class RegistryController implements IRegistryController {
	filterInfo: {
		filterPanel: BehaviorSubject<IFilterPanel>;
		filterPanelSettings: FilterPanelSettings;
	};

	data: {
		error: string;
		search: {
			fields: RegistryFieldInfo[];
			fieldId: string;
			fieldTitle: string;
			text: string;
		};

		registry: RegistryDescription;
		registryData: RegistryResponse;

		fields: RegistryFieldViewInfo[];
		displayFields: RegistryFieldViewInfo[];
	};

	state: IRegistryControllerState;

	fieldsHelper: RegistryFieldsHelper;
	selection: MultiSelectable<any>;
	paging: RegistryPagingInfo;
	btnExport: RegistryBtn;

	protected $window: any;
	protected $document: any;
	protected $http: ng.IHttpService;
	protected $location: ng.ILocationService;
	protected $longWork: LongWorkService;
	protected repository: RegistryRepository;

	private downloadService: any;

	public registryController: IRegistryController;
	public registry: RegistryInfo;

	/*@ngInject*/
	constructor(
		private $injector,
		private $scope: ng.IScope,
		private $appLoader: AppLoader,
		protected $dialogs: DialogsService,
		protected $uibModal: ng.ui.bootstrap.IModalService,
		protected $alerts: AlertsService,
		public language
	) {

		this.$http = this.$injector.get("$http");
		this.$window = this.$injector.get("$window");
		this.$document = this.$injector.get("$document");
		this.$location = this.$injector.get("$location");
		this.downloadService = this.$injector.get("downloadService");
		this.$longWork = this.$injector.get("$longWork");

		this.repository = new RegistryRepository(this.$http, this.$dialogs, this.$longWork);

		this.state = {
			dataReady: false,
			loading: false,
			emptyData: false,
			emptyFilter: false,
			selectable: false,
			withMultiSelection: false,
			exporting: false,
			initing: true
		};

		this.filterInfo = {
			filterPanel: new BehaviorSubject<IFilterPanel>(),
			filterPanelSettings: null
		};

		this.fieldsHelper = new RegistryFieldsHelper(this);

		this.selection = new MultiSelectable();

		this.data = {
			error: null,
			registry: null,
			registryData: null,
			search: {
				fieldId: null,
				fieldTitle: null,
				text: "",
				fields: []
			},
			fields: null,
			displayFields: null
		};

		this.paging = {
			page: 1,
			pageSize: 50,
			currentPageSize: null,
			totalRows: 0
		};

		$scope.$watch(() => this.paging.currentPageSize, this.watch.bind(this)); // не был виден контекст в методе

		//this.init();
	}

	$onInit() {
		this.registryController = this;
		if (this.registry) {
			this.registry = Object.assign({}, defRegistryInfo, this.registry);
			//todo. убрать
			this.registry.filterPanelStyles.compact = this.registry.compactFilters || this.registry.filterPanelStyles.compact;
			this.init();
		}
	}

	$onChanges(changesObject: any) {
		if (changesObject.registry && !changesObject.registry.isFirstChange()) {
			this.registry = changesObject.registry.currentValue;
			this.$onInit()
		}
	}

	watch(newVal: number, oldVal: number) {
		if (newVal && (newVal < 1 || newVal > 999)) {
			this.paging.currentPageSize = oldVal;
		}
	}

	public clickRow(event: any, row: any) {
		let clickOnTag = event.target && event.target.tagName;
		if (clickOnTag === "A") {
			//исключаем нажатие на линках
			return;
		}

		if (!this.state.selectable) {
			return;
		}

		if (!this.state.withMultiSelection) {
			//эмулирование единственности выбора
			if (!this.selection.isSelected(row)) {
				this.selection.dropSelect();
			}
		}
		this.selection.select(row);
	}

	//инициализация кнопок и действий и их правил показа
	private initCommandButtons() {
		const commands = this.data.registry.commands;
		const buttons = this.registry.buttons;

		const checkSelectionMode = (mode: SelectionMode, defaultVal: boolean): boolean => {
			if (mode === SelectionMode.Empty) {
				return this.selection.selected.length === 0;
			}
			else if (mode === SelectionMode.Single) {
				return this.selection.selected.length === 1;
			} else if (mode === SelectionMode.Multiple) {
				return this.selection.selected.length > 0;
			}
			return defaultVal;
		}

		this.state.withMultiSelection = false;
		if (commands && commands.length) {
			//если есть команды с необходимостью выбора - то возможность выбора есть
			this.state.selectable = commands.findIndex(c => c.mode != SelectionMode.Empty) != -1;
			this.state.withMultiSelection = commands.find(c => c.mode == SelectionMode.Multiple) !== null;
			commands.forEach((cmd) => { cmd.isEnabled = () => checkSelectionMode(cmd.mode, false); });
		}

		if (buttons && buttons.length) {
			this.state.selectable = this.state.selectable || buttons.find((b) => b.selectionMode !== null) != null;
			this.state.withMultiSelection = this.state.withMultiSelection || buttons.findIndex(b => b.selectionMode == SelectionMode.Multiple) !== -1;
			buttons.forEach((btn) => {
				btn.isEnabled = () => { return checkSelectionMode(btn.selectionMode, true); };
				btn.style = btn.style || "btn-default";
			});
		}
	}

	private init() {
		this.state.initing = true;

		this.btnExport = {
			title: this.language.Generic.Common.kBtnExcel,
			action: () => this.export(),
			icon: "glyphicon glyphicon-export",
		};

		this.repository.getDescription(this.registry.url)
			.then(registry => {
				this.data.registry = registry;

				const fpInfo = registry.filterPanel.filterPanel;
				const fpSources = registry.filterPanel.filterSources;

				this.initFilterSources(fpSources);

				this.initCommandButtons();

				//первичная инициализация полей реестра
				this.data.fields = <RegistryFieldViewInfo[]>registry.fields.filter((f) => f.default);
				this.$appLoader.hide();

				this.filterInfo.filterPanelSettings = {
					url: this.registry.filtersUrl,
					info: fpInfo,
					sources: fpSources,
					styles: this.registry.filterPanelStyles,
					events: {
						ready: () => {
							this.state.emptyFilter = false;
							this.setSearchFields();
							this.state.initing = false;
							this.$scope.$emit("FilterPanelInitialized", this.filterInfo.filterPanel.getValue());
							this.$scope.$applyAsync();
						},
						emptyChoice: () => {
							this.state.emptyFilter = true;
							this.$scope.$applyAsync();
						}
					}
				}

				//this.setSearchFields();
				this.loadingState();
			}, (response) => {
				this.$appLoader.hide();
				this.data.error = (response.data && response.data.message) || "Ошибка загрузки реестра";
			});

	}

	private initFilterSources(sources: FilterSource[]) {
		let filtersValues = this.registry.filtersValues;

		if (!filtersValues) {
			return;
		}

		let filterIds = Object.keys(filtersValues);

		filterIds.forEach((filterId) => {
			let source = sources.find(x => x.filterId === filterId);
			if (!source) {
				return;
			}
			source.defaultValue = filtersValues[filterId].toString();
		});
	}

	private loadingState() {
		this.repository.getState(this.registry.url)
			.then((registryState) => {
				let defRegistryState: RegistryState = {
					fields: [],
					search: null,
					order: null,
					paging: {
						page: 1,
						pageSize: this.registry.initialPageSize,
						currentPageSize: this.registry.initialPageSize
					}
				}

				let needLoad = this.data.registry.autoLoad;
				if (!registryState) {
					this.paging = angular.extend(this.paging, defRegistryState.paging);
				} else {
					needLoad = true;
					this.paging = angular.extend(this.paging, registryState.paging);
					if (!this.paging.pageSize) {
						this.paging.pageSize = this.registry.initialPageSize;
					}
					this.paging.currentPageSize = this.paging.pageSize;
					if (registryState.fields) {
						this.data.fields = <RegistryFieldViewInfo[]>this.data.registry.fields.filter((item) => registryState.fields.indexOf(item.id) != -1);
					}
					if (registryState.search && registryState.search.text) {
						let stateSearchField = this.data.registry.fields.find(x => x.id === registryState.search.fieldId);
						this.data.search.fieldTitle = stateSearchField.title;
						this.data.search.fieldId = stateSearchField.id;
						this.data.search.text = decodeURIComponent(registryState.search.text);
					}
					if (registryState.order && registryState.order.fieldId) {
						this.fieldsHelper.initDisplayFilters();

						let orderFieldId = registryState.order.fieldId.charAt(0).toLowerCase() + registryState.order.fieldId.substring(1);

						let stateOrderField = this.data.fields.find(f => f.id == orderFieldId);
						if (stateOrderField == null) {
							throw "Не обнаружено поле c идентификатором " + registryState.order.fieldId;
						}
						this.data.displayFields.forEach(f => f.sortOrder = null);
						stateOrderField.sortOrder = registryState.order.ascending ? OrderDirection.asc : OrderDirection.desc;
					}
				}
				if (needLoad) {
					this.load();
				}
				this.state.initing = false;
				this.$appLoader.hide();
			})
			.catch(() => {
				this.state.initing = false;
				this.$appLoader.hide();
				this.data.error = "Ошибка загрузки реестра";
			});
	}


	public setSearchField(field) {
		if (this.data.search && this.data.search.fieldId && this.data.search.fieldId === field.id && this.data.search.fieldTitle === field.title) {
			return;
		}
		this.data.search.text = "";
		this.data.search.fieldTitle = field.title;
		this.data.search.fieldId = field.id;
	}

	canExport() {
		const exportWarn = "Экспорт возможен только в случае заполненного фильтра \"Фамилия\"";

		const searchNotByLastname = () => {
			const lastNameId = "lastName";

			let searchFilter = this.data.search;

			return searchFilter.text && searchFilter.fieldId !== lastNameId;
		}

		if (searchNotByLastname()) {
			alert(exportWarn);
			return false;
		}

		return true;
	}

	equalArrays(array1, array2) {
		if (!array1 || !array2) {
			return false;
		}
		return !_.chain(array1)
			.difference(array2)
			.union(_.difference(array2, array1))
			.value()
			.length;
	}

	private setSearchFields() {
		let availableFields = this.fieldsHelper.initAvailableFields();
		let availableFieldsArr = _.pluck(availableFields, "id");

		this.data.search.fields = this.data.registry.fields
			.filter((f) => f.search)
			.filter((item) => availableFieldsArr.find((availableField) => availableField === item.id) !== null);

		if (this.data.search.fields.length) {
			let searchField = this.data.search.fields.find((f) => f.default);
			searchField = this.data.search.fields.find((f) => f.searchByDefault) || searchField;
			if (this.data.search && this.data.search.fieldId && _.some(this.data.search.fields, (fld) => fld.id === this.data.search.fieldId) && this.data.search.fieldId !== searchField.id) {
				return;
			}
			this.setSearchField(searchField);
		}
	}

	public setSearch(field: RegistryFieldViewInfo) {
		let text = "";
		if (this.data.search && this.data.search.fieldId === field.id) {
			text = this.data.search.text;
		}

		var modalInstance = this.$uibModal.open({
			template: SetRegistryFieldSearchComponent.template,
			controllerAs: SetRegistryFieldSearchComponent.controllerAs,
			controller: SetRegistryFieldSearchComponent.controller,
			resolve: {
				search: () => text,
				field: () => field
			}
		});

		modalInstance.result.then((search) => {
			if (search) {
				this.data.search = $.extend(this.data.search, {
					fieldId: field.id,
					fieldTitle: field.title,
					text: search
				});
			} else {
				this.data.search.text = "";
			}
			this.load();
		});
	}

	public clearSearch() {
		this.data.search.text = "";
		this.load();
	}

	public setSortOrder(field: RegistryFieldViewInfo, newOrder: OrderDirection) {
		if (!newOrder) {
			if (!field.sortOrder) {
				newOrder = OrderDirection.asc;
			} else {
				newOrder = field.sortOrder === OrderDirection.asc ? OrderDirection.desc : OrderDirection.asc;
			}
		}

		this.data.displayFields.forEach(f => f.sortOrder = null);
		field.sortOrder = angular.copy(newOrder);
		this.load();
	}

	public pageChange() {
		if (this.state.loading) {
			return;
		}
		this.load();
	}

	//загрузка данных
	public load() {

		const errorHandle = (message) => {
			this.data.error = message;
			this.state.dataReady = true;
			this.state.loading = false;
		}

		//инициализация запрашиваемых полей
		const initRequestField = () => {
			let fp = this.filterInfo.filterPanel.getValue();

			const filterValues = fp.getValues();

			const chain = _.chain(this.data.fields)
				.filter((field) => {
					if (!field.dependencies) {
						return true;
					}
					return new DependencyTracker(field.dependencies).isSatisfied(filterValues);
				})
				.pluck("id");

			return chain.value();
		}

		const setLoadingState = () => {
			const body = this.$document.find("body");
			scrollable = body.scrollHeight > this.$document[0].documentElement.clientHeight;

			this.state.dataReady = false;
			this.state.loading = true;
			this.selection.dropSelect();

			if (scrollable) {
				body.css({ "padding-right": "17px" });
			}
		}

		const unsetLoadingState = () => {
			const body = this.$document.find("body");
			if (scrollable) {
				body.css({ "padding-right": "" });
			}

			this.state.dataReady = true;
			this.state.loading = false;
		}

		let fp = this.filterInfo.filterPanel.getValue();

		if (!fp.validate()) {
			return;
		}
		setLoadingState();

		if (!this.paging.currentPageSize) {
			this.paging.currentPageSize = this.registry.initialPageSize;
		}

		let data: RegistryRequest = {
			filterContext: {
				selectedData: fp.getCtxValues()
			},
			fields: initRequestField(),
			page: this.paging.page,
			pageSize: this.paging.currentPageSize,
			search: null,
			order: null
		};

		if (this.data.search.fieldId && this.data.search.text) {
			data.search = {
				fieldId: this.data.search.fieldId,
				text: this.data.search.text
			};
		}

		let orderField: RegistryFieldViewInfo;
		if (this.data.displayFields) {
			let orderField = this.data.displayFields.find(f => typeof (f.sortOrder) !== "undefined" && f.sortOrder != null);
			if (orderField) {
				data.order = {
					fieldId: orderField.id,
					ascending: orderField.sortOrder === OrderDirection.asc
				}
			}
		}

		this.repository.getData(this.registry.url, data)
			.then((registryData) => {
				this.data.error = null;

				try {

					this.data.registryData = registryData;
					this.paging.pageSize = this.paging.currentPageSize;
					//инициализация пейджинга
					if (this.paging.page !== this.data.registryData.page) {
						this.paging.page = this.data.registryData.page;
					}
					this.paging.totalRows = this.data.registryData.totalItems;

					//инициализация полей реестра
					this.fieldsHelper.initDisplayFilters();

					//инициализация сортировки
					const defOrder = this.data.registry.defaultOrder;
					if (orderField) {
						const orderFieldInDisplayFields = this.data.displayFields.find(f => f.id == orderField.id);
						if (!orderFieldInDisplayFields) {
							this.data.displayFields.forEach(f => f.sortOrder = null);
							orderField = null;
						}
					}
					if (!orderField && defOrder) {
						//todo. наверное нужно заменить this.data.registry.fields на this.data.fields
						orderField = <RegistryFieldViewInfo>this.data.registry.fields.find(x => x.id == defOrder.fieldId);
						if (orderField) {
							orderField.sortOrder = defOrder.ascending ? OrderDirection.asc : OrderDirection.desc;
						}
					}

					//установка номеров строк
					this.data.registryData.rows.forEach((row, ind) => row.rownum = ((this.paging.page - 1) * this.paging.pageSize) + ind + 1);
				} catch (ex) {
					errorHandle("Ошибка обработки данных: " + ex.message);
					return;
				}
				unsetLoadingState();
				this.state.emptyData = !registryData.rows.length;
			},
				(response) => {
					if (response && response.status === 401) {
						this.$dialogs.message(this.language.Generic.Common.kTimeOutOccured4Ajax).then(() => this.$window.location.pathname = "/");
						return;
					}
					errorHandle("Ошибка загрузки данных " + (response && response.data ? response.data.message + (response.data.details ? " " + response.data.details : "") : ""));
				});

	}

	public clearLoad() {
		this.paging.page = 1;
		if (this.data.search.fieldId
			&& this.data.search
			&& this.data.search.fields
			&& this.data.search.fields.length
			&& !this.data.search.fields.find((item) => item.id === this.data.search.fieldId)) {
			this.data.search.fieldId = this.data.search.fields[0].id;
			this.data.search.text = null;
		};
		this.load();
	}

	//экспорт данных
	public export() {

		const getDefaultExportFields = () => {
			let exportFields = this.data.displayFields;

			if (exportFields) {
				exportFields = exportFields.filter((field) => { return field.default; });
			}

			return exportFields;
		}

		if (!this.data.displayFields) {
			this.fieldsHelper.initDisplayFilters();

			this.data.displayFields = getDefaultExportFields();
		}

		let fp = this.filterInfo.filterPanel.getValue();

		if (!fp.validate()) {
			return;
		}

		let data: RegistryRequest = {
			filterContext: {
				selectedData: fp.getCtxValues()
			},
			fields: _.pluck(this.data.displayFields, "id"),
			search: this.data.search,
			order: null,
			page: null,
			pageSize: null
		};

		let orderField = this.data.displayFields.find(f => typeof (f.sortOrder) != "undefined" && f.sortOrder != null);
		if (orderField) {
			data.order = {
				fieldId: orderField.id,
				ascending: orderField.sortOrder === OrderDirection.asc
			}
		}

		this.state.exporting = true;
		const wait = this.$dialogs.wait("Операция выполняется");
		this.repository.exportData(this.registry.url, data)
			.then((fileId) => {
				wait.close();

				const isValidTempFileId = /^[0-9a-f]{24}$/i.test(fileId);
				if (!isValidTempFileId) {
					this.$alerts.error("Ошибка экспорта данных.", "Неизвестный ответ");
					return;
				}

				this.downloadService.downloadFile(`/webapi/files/${fileId}`);
				this.state.exporting = false;
			},
				(response) => {
					this.state.exporting = false;
					this.$alerts.error("Ошибка экспорта данных.", response.data && response.data.message);
					wait.close();
				});
	};

	//выполнение команды реестра
	public execCmd(cmd: RegistryCommandInfo) {
		const confirms = [];
		if (cmd.confirm) {
			confirms.push(() => this.$dialogs.confirm(cmd.confirm));
		}

		extDeferred.when(confirms).then(() => {

			const wait = this.$dialogs.wait("Операция выполняется");
			const data = {
				itemId: _.pluck(this.selection.selected, "id")
			};

			this.repository.execCommand(this.registry.url, cmd.id, data)
				.then((result) => {
					wait.close();
					if (result.success) {
						this.$dialogs.message(result.message);
						this.load();
					} else {
						this.$dialogs.error(result.message);
						if (result.needReload) {
							this.load();
						}
					}
				},
					(response) => {
						this.$dialogs.error(response.data && response.data.message, "Ошибка выполнения команды");
						wait.close();
					});

		});


	};

	//настройки
	public settings() {
		const availableFields = this.fieldsHelper.initAvailableFields();
		const oneCheckedOnly = (checked) => {
			return checked && _.countBy(chooseFields, (field) => field.selected ? 'checked' : 'notChecked').checked === 1;
		}

		let chooseFields: RegistryFieldChooseModel[] = availableFields
			.map(f => ({
				id: f.id,
				title: f.title,
				selected: this.data.fields.find(x => x.id == f.id) ? true : false,
				oneCheckedOnly: (checked) => oneCheckedOnly(checked)
			}));

		var modalInstance = this.$uibModal.open({
			template: RegistrySettingsComponent.template,
			controller: RegistrySettingsComponent.controller,
			controllerAs: RegistrySettingsComponent.controllerAs,
			resolve: {
				fields: () => chooseFields
			}
		});

		modalInstance.result.then((fields: RegistryFieldChooseModel[]) => {
			let currentFieldsIds = this.data.fields.map(f => f.id);
			let choosingFieldsIds = fields.map(f => f.id);
			let selectedFieldsIds = fields.filter(f => f.selected).map(f => f.id);

			//todo. что тут творится?
			let fieldIds: string[] = _.chain(this.data.registry.fields)
				.pluck("id")
				.difference(choosingFieldsIds)
				.intersection(currentFieldsIds)
				.union(selectedFieldsIds)
				.value();

			let notSelectedFields = this.data.fields.filter(f => fieldIds.indexOf(f.id) == -1);
			notSelectedFields.forEach(f => f.sortOrder = null);

			this.data.fields = <RegistryFieldViewInfo[]>this.data.registry.fields.filter(item => fieldIds.indexOf(item.id) !== -1);
			this.data.displayFields = this.data.displayFields.filter(item => fieldIds.indexOf(item.id) !== -1);

			this.load();
		});
	};
}

export const RegistryFieldDirective = ($compile: ng.ICompileService) => {

	var linker = (scope, element) => {
		const decorator: Decorator = scope.field.decorator;

		scope.content = scope.row[scope.field.id];

		let template = "<span>{{content}}</span>";
		if (decorator) {
			if (decorator.type) {
				//устаревшее. оставлено для обратной совместимости
				if (decorator.type === "link") {
					scope.action = (<any>decorator).action;
					template = `<a href="javascript:void(0);" ng-click="action(row, filterInfo)">{{content}}</a>`;
				}
				if (decorator.type === "map") {
					scope.content = (<any>decorator).map(scope.content);
				}
				if (decorator.type === "preserveWhiteSpace") {
					element.css("white-space", "pre-line");
				}
				if (decorator.type === "text-center") {
					element.parent().addClass("text-center");
				}
			}

			if (decorator.activate) {
				decorator.activate(scope, element);
			}
			if (decorator.template) {
				template = decorator.template;
			}
		}
		element.html(template).show();
		$compile(element.contents())(scope);
	};

	return {
		restrict: "E",
		replace: true,
		link: linker,
		scope: {
			field: "=",
			row: "=",
			filterInfo: "="
		}
	};
};

class RegistrySettingsController {
	/*@ngInject*/
	constructor(
		private $uibModalInstance: ng.ui.bootstrap.IModalInstanceService,
		public fields: any[]
	) {
	}

	cancel() {
		this.$uibModalInstance.dismiss("cancel");
	}

	set() {
		this.$uibModalInstance.close(this.fields);
	}
}

