import { LoggerFactory, Logger } from "../logging";
import { ISelectable } from "../models/common.model";
import { EventEmitter } from "../models/common.reactive";

declare var angular: ng.IAngularStatic;

/*@ngInject*/
export const TrackChangesDirective = (changeTracker) => {
	return {
		link: (scope, element) => {
			let modalDialog = $(element).closest("div.modal.fade");
			let isUiSelect = $(element).hasClass("ui-select-container");
			let context = modalDialog.length ? modalDialog : undefined;
			const wasChangedFunc = () => {
				changeTracker.dataWasChanged(context);
				scope.$applyAsync();
			}
			if (isUiSelect) {
				element.on("click", wasChangedFunc);
				element.on("keydown", wasChangedFunc);
			} else {
				element.on("change", wasChangedFunc);
			}
		}
	}
}

export const IndeterminateDirective = () => {
	return {
		restrict: "A",
		link: (scope, element, attributes) => {
			scope.$watch(attributes["ngIndeterminate"], function (value) {
				element.prop("indeterminate", !!value);
			});
		}
	};
}

export const HighliteInputTableRowDirective = () => {
	return {
		restrict: 'A',
		link: function (scope, element) {
			element.on("blur", "td.input-cell > input", function () {
				var row = $(this).closest("tr");
				row.removeClass("selected");
			});

			element.on("focus", "td.input-cell > input", function () {
				var row = $(this).closest("tr");
				row.addClass("selected");
			});
		}
	}
}
declare var dateUtils: any;

/*@ngInject*/
export const NsDateModel2Directive = ($timeout) => {
	const toStr = function (dateParam) {
		return dateParam ? dateUtils.date2str(new Date(dateParam)) : null;
	}
	return {
		restrict: 'A',
		require: 'ngModel',
		link: (scope, element, attr, ngModel) => {
			ngModel.$formatters.push(function (raw) {
				if (raw == null || raw == "") {
					return "";
				}
				if (typeof raw == "string") {
					return toStr(raw);
				}
				let str = dateUtils.date2str(raw);
				return str;
			});

			ngModel.$parsers.push(function (raw) {
				if (raw == null || raw == "") {
					return null;
				}
				let date = dateUtils.str2date(raw);
				return date;
			});

			element.on('paste', function ($event) {
				let data = $event.originalEvent.clipboardData;
				if (typeof (data) !== "undefined") {
					let pastValue = data.getData("text/plain");
					$timeout(() => {
						ngModel.$setViewValue(pastValue);
					});
					return;
				}

				$timeout(() => {
					let pastValue = element.val();
					ngModel.$setViewValue(pastValue);
				}, 100);

			});
		}
	}
}


