declare var angular : ng.IAngularStatic;

import { PageContext } from "approot/global/services/context";
import { postTo } from "webroot/static/src/common/js/common.navigation";

export class BreadcrumbRouting {
	/*@ngInject*/
	constructor(
		private pageContext: PageContext, 
		private $location: ng.ILocationService, 
		private $window: ng.IWindowService) {
	}

	confirmAndLeave(scope: any, leave: () => void) {
		if (scope.confirmAndLeave) {
			scope.confirmAndLeave(leave);
			return;
		}

		if (this.pageContext.confirmAndLeave) {
			this.pageContext.confirmAndLeave(leave);
			return;
		}
	}

	getPageContext($scope: ng.IScope): PageContext {
		if (this.pageContext && this.pageContext.title) {
			return this.pageContext;
		}
		return $scope["page"];
	}

	private goBack(scope: ng.IScope, backUrl: string){
		if (backUrl.indexOf(".asp") > 0 || backUrl.indexOf("/angular/") == 0) {
			//если указан href на asp страницу или ангулар страницу другого модуля
			postTo(backUrl);
		} else {
			//если указан href - angular страницу
			this.$location.path(backUrl).search({});
			if (!scope.$$phase) {
				scope.$apply();
			}
		}
	}

	back(scope: ng.IScope) {
		let currentPageCtx = this.getPageContext(scope);

		const backInfo = currentPageCtx.back;
		const backInfoHref = backInfo && backInfo.href;
		const backHref = backInfoHref || (currentPageCtx.parent && currentPageCtx.parent.href);

		if (backInfo && backInfo.history) {
			//браузерный бэк
			if (this.$window.routeChanges > 1) {
				this.$window.routeChanges = this.$window.routeChanges - 2; /* Т.к. при смене маршрута (событие $routeChangeStart) добавляется +1 */
				this.$window.history.back();
				return;
			} 
			
			if (!backInfoHref) {
				postTo(document.referrer);
				return
			}

			this.goBack(scope, backHref);
			return;
		}

		if (backHref) {
			this.goBack(scope, backHref);
			return;
		}

		// Недоступен контект
		//$window.history.back();
	}

	toTitle(scope: ng.IScope) {
		if (!scope) {
			console.error("Scope is not available");
			return;
		}
		let currentPageCtx = this.getPageContext(scope);
		if (currentPageCtx.parent) {
			if (currentPageCtx.parent.postTo || currentPageCtx.parent.href.indexOf(".asp") > 0) {
				postTo(currentPageCtx.parent.href);
			} else {
				this.$location.path(currentPageCtx.parent.href).search({});
				if (!scope.$$phase) {
					scope.$apply();
				}
			}
		}
	}
}

/*@ngInject*/
export const PageTitleDirective = (breadcrumbRouting: BreadcrumbRouting) => ({
	replace: true,
	link: (scope: ng.IScope, element: JQuery<HTMLElement>) => {
		let leave = () => breadcrumbRouting.toTitle(scope);
		let confirmAndLeave = () => breadcrumbRouting.confirmAndLeave(scope, leave);

		element.attr("href", "javascript:void(0);");
		element.on("click", ".parent-page-link", confirmAndLeave);

		scope["hasParentPage"] = () => {
			let pageContext = breadcrumbRouting.getPageContext(scope);
			return pageContext && pageContext.parent && pageContext.parent.title;
		}

		scope["getPageContext"] = () => breadcrumbRouting.getPageContext(scope);
	},
	template: `<h1 class='title'>`
					+ `<a data-ng-bind-html='getPageContext().parent.title' ng-if='hasParentPage()' class='parent-page-link' href='#'></a>`
					+ `<span ng-if='hasParentPage()' class='title-delim'>/</span>`
					+ `<span data-ng-bind-html='getPageContext().title'></span>`
			+ `</h1>`
});

/*@ngInject*/
export const PageBackDirective = (breadcrumbRouting: BreadcrumbRouting) => ({
	replace: true,
	link: (scope: ng.IScope, element: JQuery<HTMLElement>) => {
		let leave = () => breadcrumbRouting.back(scope);
		let confirmAndLeave = () => breadcrumbRouting.confirmAndLeave(scope, leave);

		element.attr("href", "javascript:void(0);");
		element.on("click", confirmAndLeave);

		scope["isActive"] = () => {
			let pageCtx = breadcrumbRouting.getPageContext(scope);
			return pageCtx && (pageCtx.back || pageCtx.parent);
		}

		scope["getPageContext"] = () => breadcrumbRouting.getPageContext(scope);
	},
	template: `<a title='Вернуться' class='back' ng-class='{active: !isActive()}'><span class='icon-signout'></span></a>`
});

angular.module('irtech.netcity.ui-components', [])
	.service("breadcrumbRouting", BreadcrumbRouting)
	.directive("pageTitle", PageTitleDirective)
	.directive("pageBack", PageBackDirective)


