"use strict";

class BaseTableController {
	constructor($scope) {
		const defaultPageSize = 25;
		this.$scope = $scope;
		let self = this;
		$scope.br = '<br />';

		$scope.$watch(() => self.model, (newModel, oldModel) => {
			if(!newModel) return;
			[self.fields, self.data] = self.prepare(newModel);
			/*
			let oldSystemName = oldModel && oldModel.type && oldModel.type.systemName;
			let newSystemName = oldModel.type && oldModel.type.systemName;
			*/
			let page = /*oldSystemName == newSystemName &&*/ $scope.paging && $scope.paging.page || 1;
			$scope.paging = {
				size: newModel.pageSize || defaultPageSize,
				page: page
			}

			$scope.messages = {
				noData: newModel.type.messages.noDataMessage || language.Generic.ServAdmin.kRefItemsEmpty,
				notFound: newModel.type.messages.notFoundMessage || language.Generic.Common.kNoMatchesFound,
			};
		});

		$scope.messages = {
			noData: language.Generic.ServAdmin.kRefItemsEmpty,
			notFound: language.Generic.Common.kNoMatchesFound,
		};

		self.filteredData = [];
		$scope.$watch(() => self.search, (newValue, oldValue) => {
			if(newValue == oldValue)
				return newValue;

			self.filteredData = [];
			if(!newValue)
				return newValue;

			this.updateFilteredData();
		});

		$scope.$watch(() => self.data, () => {
			this.updateFilteredData();
		});
	}

	updateFilteredData() {
		let self = this;
		self.filteredData = [];
		if (this.search == undefined)
			return;

		let searchString = this.search.toLowerCase();
		for (let index in self.data) {
			let row = self.data[index];
			for (let prop in row) {
				let field = self.fields.find(f => f.systemName == prop);
				if (!field || field.isHidden || prop != "name" && prop != "shortName") continue;

				let value = row[prop].toString().toLowerCase();
				let text = (field && self.getText(row, field).toString() || "")
					.toLowerCase();
				if (text.includes(searchString) || value.includes(searchString)) {
					self.filteredData.push(row);
					break;
				}
			}
		}
	}

	prepareDate(line){
		let data = angular.copy(this.fields);
		for(let index in data){
			let prop = data[index];
			prop.value = line[prop.systemName];
		}
		return data;
	}

	select(line) {
		if (line.isUsed != "System") {
			let data = this.prepareDate(line);
			this.onSelect({ data: data })
		}
	}

	isEditable(column){
		return column.isMain;// && !!this.onEdit;
	}

	edit(line){
		let data = this.prepareDate(line);
		this.onEdit({data: data});
	}

	isSystem(line) {
		return line.isUsed == "System";
	}

	isFree(line) {
		return line.isUsed == "Free";
	}

	isSelected(line) {
		return line.isSelected;
	}

	/* Метод подготовки модели к использованию
	* Должен вернуть массив из 3х массивов
	* [0] -- массив заголовков
	* [1] -- массив данных
	* [2] -- массив подвала
	*/
	prepare(model) {
		if(!model) return;

		for(let index in model.fields){
			let field = model.fields[index];
			if(field.isHidden) continue;

			//Todo подумать нужно ли автоскрытие пустых полей
			//field.isHidden = !model.data.filter(o => !!o[field.systemName]).length;
		}
		return [
			model.fields.sort((a,b) => a.order - b.order),
			model.data
		];
	}

	getData() {
		return !this.search ? this.data : this.filteredData;
	}

	getPage(page, size) {
		return this.getData().slice((page-1)*size, page * size);
	}

	showPaging() {
		let data = this.getData();
		return data && (data.length > this.$scope.paging.size);
	}

	getText(line, column) {
		const toCamelCase = (str) => str && `${str[0].toLocaleLowerCase()}${str.slice(1)}`;

		let value = line[column.systemName];

		if(column.type === "Date"){
			let date = new Date(value);
			return dateUtils.date2str(date);
		}

		if(column.availableValues){
			let cameledValue = typeof(value) === "string"
				? toCamelCase(value)
				: value;
			let data = column.availableValues[cameledValue];
			return !!data ? data.name : '-';
		}
		return value;
	}
}

BaseTableController.$inject = ["$scope"];
const tableControllerName = "BaseTableCtrl";

let tableComponent = {
	templateUrl: "/static/dist/app/global/ui-components/codebaseView/table/tableTemplate.html",
	controller: tableControllerName,
	controllerAs: "$ctrl",
	bindings: {
		model: "=ngModel",
		onSelect: "&onSelect",
		onEdit: "&onEdit",
		search: "=",
	}
}

const moduleNamespace = 'irtech.netcity.ui-components';
const moduleName = 'tableView';

angular.module(moduleNamespace)
	.controller(tableControllerName, BaseTableController)
	.component(moduleName, tableComponent);


