import { FilterModel, IFilterPanel, IFilter, FilterSource, FilterStatus, FilterDependency } from "./filterpanel.model";
import { DependencyTracker } from "./dependencyTracker";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { UnderscoreStatic } from "underscore";

declare var _: UnderscoreStatic;
declare var Handlebars: any;

export abstract class Filter implements IFilter {
	public id: string;
	public emptyChoice: boolean;
	public filterRow: JQuery<HTMLElement>;
	public control: JQuery<HTMLElement>;

	public choice: any;
	
	public status: FilterStatus;
	public choiceEnabling: boolean;
	public existStateProvider: boolean;

	constructor(protected $dialogs: DialogsService, public panel: IFilterPanel, public model: FilterModel) {
		this.id = this.model.id;

		this.emptyChoice = false;
		this.filterRow = null;
		this.choice = null;

		this.choiceEnabling = true;
		this.existStateProvider = this.model.existStateProvider;

		let filterSize = this.panel.filterSize;

		let label = "<label class=\"" + filterSize.label + "\">{{{title}}}</label>";
		let control = "<div class=\"" + filterSize.control + "\">";
		let row = '<div class="form-group">' + label + control + '<div id="filter-control"></div> </div> </div>';

		let template = Handlebars.compile(row);
		let html = template({
			title: this.model.title
		});
		this.filterRow = $(html);
	}

	appendToPanel(panel: JQuery<HTMLElement>) {
		this.filterRow.find("#filter-control").replaceWith(this.control);

		return panel.append(this.filterRow);
	}

	changeStatus(status: FilterStatus) {
		this.filterRow.removeClass(this.status);
		this.status = status;
		this.filterRow.addClass(this.status);
		switch (status) {
			case FilterStatus.inactive:
				this.disable();
				break;
			case FilterStatus.active:
				this.enable();
				break;
		}
	}

	getChoiceEnabling() {
		return this.choiceEnabling;
	}

	setChoiceEnabling(choiceEnabling: boolean) {
		return this.choiceEnabling = choiceEnabling;
	}

	getStatus() : FilterStatus {
		return this.status;
	}

	getChoice() {
		return this.choice;
	}

	getChoiceText() {
		return this.choice;
	}

	setChoice(choice: any): void {
		let prevChoice = this.choice;
		this.choice = choice;
		this.panel.changedValue(this, choice, prevChoice);
		this.filterRow.trigger(this.id + ':change', [choice, prevChoice, this]);
	}

	setSource(src: FilterSource) {
		if (src.defaultValue || (src.defaultValue === "")) {
			return this.setChoice(src.defaultValue);
		}
	}

	getDependency() : IFilter[] {
		let testFilters = this.panel.filters.filter((item) => {
			return item.model.order > this.model.order;
		});

		let dependentFilters: IFilter[] = [];
		for (const testFilter of testFilters) {
			let testFilterModel = testFilter.model;
			if (!testFilterModel.dependencies) {
				continue;
			}

			let fltFunc = (dependency : FilterDependency) => {
				return (dependency.relatedObject.type === "Filter") && dependency.relatedObject.ref === this.model.id;
			};

			if (!_.some(testFilterModel.dependencies, fltFunc)) {
				continue;
			}
			dependentFilters.push(testFilter);
		}

		for (const dependentFilter of dependentFilters) {
			let subDependentFilters = dependentFilter.getDependency();
			if ((subDependentFilters != null ? subDependentFilters.length : void 0) === 0) {
				continue;
			}
			subDependentFilters = subDependentFilters.filter(subDepFlt => dependentFilters.findIndex(f => f.id == subDepFlt.id) == -1);
			if (subDependentFilters.length === 0) {
				continue;
			}
			dependentFilters = _.union(dependentFilters, subDependentFilters);
		}

		return dependentFilters;
	};

	dependenciesSatisfied() : boolean {
		let vals = this.panel.getValues();
		let tracker = new DependencyTracker(this.model.dependencies);
		return tracker.isSatisfied(vals);
	};

	abstract enable(): void;
	abstract disable(): void;

	validate() : boolean {
		return true;
	}
}



