import { ChangeTracker } from "../changeTracker";

declare var dateUtils: any;
declare var dateInput: any;

class DateValidator {
	constructor(public strDate: string) { }

	validateDateFormat(): boolean {
		return Date.parse(this.strDate) && dateUtils.str2date(this.strDate);
	}
}

/*@ngInject*/
export const NsDateInputDirective = ($timeout, changeTracker: ChangeTracker) => {
	const toStr = function (dateParam) {
		return dateParam ? dateUtils.date2str(new Date(dateParam)) : null;
	}

	const initDatepicker = function (component: any, options: any) {
		dateInput.initDateInput(component,
			options.calendarMinDate || null,
			options.calendarMaxDate || null,
			options.calendarSettings || null,
			options.datePickerOptions || null, true);
	}

	const onChange = function () {
		changeTracker.dataWasChanged();
	}

	return {
		restrict: 'A',
		require: "ngModel",
		scope: {
			required: "=requiredValue",
			options: "=?",
			minDate: "=?",
			maxDate: "=?",
			dateChange: "=?"
		},
		link: (scope: any, element: any, attrs: ng.IAttributes, ngModel: ng.INgModelController) => {
			// инициализация
			initDatepicker(element.closest(".input-group.date"), scope.options || {});

			let validator: DateValidator = null;
			let initValidator = (viewValue: string) => {
				if (validator == null || validator.strDate !== viewValue) {
					validator = new DateValidator(viewValue);
				}
			}

			ngModel.$formatters.push(function (raw) {
				if (raw == null || raw == "") {
					return "";
				}

				if (typeof raw == "string") {
					return toStr(raw);
				}

				let str = dateUtils.date2str(raw);

				if (scope.required) {

				}

				return str;
			});

			ngModel.$parsers.push(function (raw) {
				if (raw == null || raw == "") {
					return null;
				}

				let date = dateUtils.str2date(raw);

				return date;
			});

			element.on('paste', function ($event) {
				let data = $event.originalEvent.clipboardData;

				if (typeof (data) !== "undefined") {
					let pastValue = data.getData("text/plain");

					$timeout(() => {
						ngModel.$setViewValue(pastValue);
						onChange();
					});

					return;
				}

				$timeout(() => {
					let pastValue = element.val();
					ngModel.$setViewValue(pastValue);
				}, 100);

			});

			element.on("change", function ($event) {
				let changeValue = element.val();
				ngModel.$setViewValue(changeValue);

				if (scope.dateChange && typeof scope.dateChange === "function") {
					scope.dateChange();
				}
			});

			// валидаторы по умолчанию
			ngModel.$validators.dateFormat = (modelValue: Date, viewValue: string) => {
				if (!scope.required && ngModel.$isEmpty(viewValue)) {
					return true;
				}

				initValidator(viewValue);

				let result = validator.validateDateFormat();

				return result;
			};

			ngModel.$validators.datePeriod = (modelValue: Date, viewValue: string) => {
				if (!scope.minDate || !scope.maxDate) {
					return true;
				}

				if (!modelValue && ngModel.$isEmpty(viewValue)) {
					if (!scope.required) {
						return true;
					}
					return false;
				}

				if (modelValue < scope.minDate || modelValue > scope.maxDate) {
					return false;
				}

				return true;
			};
		}
	}
}

export const DateInputComponent = {
	template: `
        <div class="input-group date" ng-if="!$ctrl.readonly">
            <input track-changes type="text" class="form-control date-input" size="11" maxlength="10" ns-date-input
                ng-model="$ctrl.dateModel" name="{{$ctrl.name}}" ng-required="$ctrl.required"
                required-value="$ctrl.required" options="$ctrl.options" min-date="$ctrl.minDate" max-date="$ctrl.maxDate" date-change="$ctrl.dateChange">
            <span class="input-group-btn">
                <button title="" type="button" class="btn btn-primary">
                    <span class="glyphicon glyphicon-calendar"></span>
                </button>
            </span>
        </div>
        <input type="text" class="form-control date-input" name="{{$ctrl.name}}" size="11" maxlength="10" ns-date-model2 ng-model="$ctrl.dateModel" disabled ng-if="$ctrl.readonly">`,
	controller: class DateInputComponentController {
		public dateModel: Date;
		public name?: string;
		public required?: boolean;
		public options?: any;
		public readonly: boolean;
		public minDate?: Date;
		public maxDate?: Date;
		public dateChange?: any;

		constructor() {
		}
	},
	selector: "dateInputComponent",
	bindings: {
		dateModel: "=",
		name: "@",
		required: "=?",
		options: "=?",
		readonly: "=?",
		minDate: "=?",
		maxDate: "=?",
		dateChange: "&?"
	},
	controllerAs: "$ctrl"
}


