window.childWindows = [];

let windowsNotCloseNames = [
	"_mail", "_forum", "_help", "_qualityAssessmentAnalytics", "_qualityAssessmentAnalyticsEM", "nsxml", "_staffAttest"
];

export const openPopupWindow = (wnd_to, url, width, height) => {
	let wnd = window.windows[wnd_to];

	if (wnd && !wnd.closed && wnd_to != "_qualityAssessmentAnalytics" && wnd_to != "_qualityAssessmentAnalyticsEM" && wnd_to != "_staffAttest") {
		wnd.forceClosing = true
		wnd.close()
	}

	if (url.lastIndexOf("?") != -1)
		url += "&"
	else
		url += "?"

	const winOptions = {
		url: url + "AT=" + appContext.at + "&VER=" + getVer(),
		name: wnd_to,
		specs: "status=yes,toolbar=no,menubar=no,location=no,scrollbars=yes,resizable=yes,directories=no,width=" + width + ",height=" + height,
		winChild: wnd
	};

	if (wnd && !wnd.closed && (wnd_to == "_qualityAssessmentAnalytics" || wnd_to == "_qualityAssessmentAnalyticsEM")) {
		wnd.focus()
		return
	}

	windowOpen(winOptions)
	wnd = window.windows[wnd_to] = winOptions.winChild
	center(wnd, width, height)
}

export const center = (wnd, width, height) => {
	if (!wnd || !wnd.screen) {
		return
	}

	if (typeof bowser !== "undefined") {
		if (bowser.webkit && parseInt(bowser.version) < 20) {
			return
		}
	}

	let dw = (wnd.screen.availWidth - width) / 2;
	let dh = (wnd.screen.availHeight - height) / 2;

	wnd.moveTo(dw, dh);
}

export const windowOpen = function (winOptions) {
	var opener, wnd;
	var url = winOptions.url || "";
	var name = winOptions.name || "";
	var specs = winOptions.specs || "";
	var replace = winOptions.replace || "";
	wnd = winOptions.winChild;
	if (wnd && !wnd.closed) {
		wnd.close();
	}
	wnd = window.open(url, name, specs, replace);
	winOptions.winChild = wnd;
	opener = wnd.opener;
	while (opener && !opener.closed) {
		try {
			opener.childWindows.push(wnd);
			opener = opener.opener;
		} catch (error) {
			break;
		}
	}
	return $(window).on("unload",
		function (e) {
			if (wnd && !wnd.closed && windowsNotCloseNames.indexOf(wnd.name) < 0) {
				wnd.forceClosing = true;
				return wnd.close();
			}
		});
};

export const closeChildWindows = function () {
	var k;
	k = window.childWindows.length;
	while (k > 0) {
		if (window.childWindows[k - 1] && !window.childWindows.closed) {
			window.childWindows[k - 1].close();
		}
		window.childWindows.pop();
		k = k - 1;
	}
};


