import { ConnectionInfo, EnqueueInfo, QueueExecutionOptions, ExecutionContext, startingStatus, TaskErrorData, TaskCompleteData, ProgressData, TaskExecutionEvent } from "./taskqueue.model";
import { LoggerFactory, Logger } from "approot/global/logging";
import { AppContext } from "../context";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { BehaviorSubject, Subject } from "approot/global/models/common.reactive";
import { TaskExecutionComponent } from "./taskexecution.component";

export class TaskQueueService {
	private connectionInfo: ConnectionInfo;
	private logger: Logger;

	/*@ngInject*/
	constructor(
		loggerFactory: LoggerFactory,
		private appContext: AppContext,
		private $dialogs: DialogsService,
		private $uibModal: ng.ui.bootstrap.IModalService,
		private language: any) {

		this.logger = loggerFactory.getInstance("taskQueueService")
	}

	public execute<T>(opt: QueueExecutionOptions): Promise<T> {
		const defOpts = {
			getTaskFunc: null,
			closeOnStart: false,
			hint: "",
			userErrorHandler: null,
			userCloseHandler: null
		};

		let opts: QueueExecutionOptions = $.extend({}, defOpts, opt);

		let ctx: ExecutionContext = {
			taskId: null,
			error: false,
			progress: false,
			connectionInfo: null
		};

		const statusSubject = new BehaviorSubject<string>();
		const taskEnqueueInfoSubject = new BehaviorSubject<EnqueueInfo | Number>();

		const eventsSubject = new Subject<TaskExecutionEvent>();

		statusSubject.subscribe((status) => this.logger.info(status))
		statusSubject.next(startingStatus);

		let processingDialog = this.$uibModal.open({
			backdrop: 'static',
			keyboard: false,
			controller: TaskExecutionComponent.controller,
			controllerAs: TaskExecutionComponent.controllerAs,
			templateUrl: TaskExecutionComponent.templateUrl,
			resolve: {
				statusSubject: () => statusSubject,
				taskEnqueueInfoSubject: () => taskEnqueueInfoSubject,
				eventsSubject: () => eventsSubject,
				logoutputMode: () => opts.logoutputMode,
				header: () => opts.header,
				hint: () => opts.hint
			}
		})

		let disposeHandler = () => {
			if (!ctx.taskId && !ctx.error) {
				return false;
			}
			if (!ctx.connectionInfo) {
				return false;
			}
			ctx.connectionInfo.queueHub = null;
			if (!ctx.connectionInfo.connection) {
				return false;
			}
			ctx.connectionInfo.connection.stop();
			if (ctx.taskId && opts.userCloseHandler) {
				return opts.userCloseHandler();
			}
		}

		processingDialog.result.then(() => disposeHandler(), () => disposeHandler());

		return new Promise((resolve, reject) => {
			let onProgress = (progressInfo: ProgressData) => {
				ctx.progress = true;
				statusSubject.next(progressInfo.Status);
			};
			let onComplete = (completeInfo: TaskCompleteData) => {
				eventsSubject.next(TaskExecutionEvent.complete);
				if (typeof (opts.closeOnEnd) == undefined || opts.closeOnEnd == null || opts.closeOnEnd) {
					processingDialog.close();
				}
				let result: T = null;
				if (completeInfo.Data[0] === "{") {
					result = <T>JSON.parse(completeInfo.Data);
				}
				else {
					//todo. проверить что тип T string
					result = <T><unknown>completeInfo.Data;
				}
				resolve(result);
			};
			let onErrorCommon = (errorInfo) => {
				eventsSubject.next(TaskExecutionEvent.complete);
				ctx.error = true;
				if (typeof (opts.closeOnEnd) == undefined || opts.closeOnEnd == null || opts.closeOnEnd) {
					processingDialog.close();
				}
				this.logger.error(errorInfo);
			};
			let onError = (errorInfo: TaskErrorData) => {
				onErrorCommon(errorInfo);
				let errMessage = errorInfo.Details || this.language.Generic.Common.kUnexpErr;
				this.$dialogs.error(errMessage);
				reject(errMessage);
			};
			let onErrorUser = (errorInfo) => {
				onErrorCommon(errorInfo);
				let errMessage = errorInfo.Details || this.language.Generic.Common.kUnexpErr;
				if (!opts.userErrorHandler) {
					this.$dialogs.error(errMessage);
				} else {
					opts.userErrorHandler(errMessage);
				}
				reject(errMessage);
			};

			this.prepareHub(onProgress, onComplete, onErrorUser)
				.then((connectionInfo) => {
					ctx.connectionInfo = connectionInfo;
					return processingDialog.opened;
				}, onError)
				.then(() => {
					return opts.getTaskFunc()
						.catch((response) => {
							ctx.error = true;
							processingDialog.close();
							reject();
							if (response && response.data && response.data.message) {
								this.$dialogs.error(response.data.message)
							}
							return null;
						})
				})
				.then((enqueueInfo: number | EnqueueInfo | null | undefined) => {
					if (enqueueInfo === null || typeof (enqueueInfo) == "undefined") {
						ctx.error = true;
						reject();
						processingDialog.close();
						return;
					}

					taskEnqueueInfoSubject.next(enqueueInfo);

					eventsSubject.subscribe((event) => {
						if (event == TaskExecutionEvent.cancel) {
							this.logger.info("Инициирована отмена задачи " + taskId);
							ctx.connectionInfo.queueHub.server.cancelTask(taskId);
						}
					});

					let taskId: number = (<any>enqueueInfo).taskId || enqueueInfo;
					this.logger.info("Успешно создана задача " + taskId);

					return ctx.connectionInfo.queueHub.server.startTask(taskId)
						.done(() => {
							this.logger.info("Успешно запущена в обработку задача " + taskId);

							ctx.taskId = taskId;
							if (opts.closeOnStart) {
								ctx.connectionInfo.connection.stop();
								this.$dialogs.message("Отчет поставлен в очередь на обработку. \n Результат выполнения придет Вам на внутреннюю почту.")
								processingDialog.close();
								return;
							}
							if (!ctx.progress) {
								statusSubject.next("В очереди обработки");
							}
						})
						.fail(onError);
				});

		})
	}

	private prepareHub(progressHandler: (data) => void, completeHandler: (data) => void, errorHandler: (data) => void): Promise<ConnectionInfo> {
		if (this.connectionInfo && this.connectionInfo.queueHub) {
			this.logger.info("connection is ready");
			return Promise.resolve(this.connectionInfo);
		}

		let connectionInfo: ConnectionInfo = {
			connection: (<any>$).connection.hub,
			queueHub: (<any>$).connection.queueHub
		};

		connectionInfo.connection.qs = {
			"at": this.appContext.at
		};

		connectionInfo.queueHub.client.progress = (data) => {
			this.logger.info("progress: ", JSON.stringify(data))
			return progressHandler(data);
		};

		connectionInfo.queueHub.client.complete = (data) => {
			this.logger.info("complete: ", JSON.stringify(data))
			completeHandler(data);
			connectionInfo.queueHub = null;
			return connectionInfo.connection.stop();
		};

		connectionInfo.queueHub.client.error = (data) => {
			this.logger.error(data)
			errorHandler(data);
			connectionInfo.queueHub = null;
			return connectionInfo.connection.stop();
		};

		return new Promise((resolve, reject) => {
			connectionInfo.connection.start()
				.done(() => {
					this.logger.debug("connection started");
					this.connectionInfo = connectionInfo;
					resolve(connectionInfo);
				})
				.fail(() => {
					this.logger.error("connection start fail");
					connectionInfo = null;
					reject("Ошибка соединения с сервером");
				});
		})
	};
}


