import { FileUploadService, FileUploadResult } from "../components/fileattachments.component";

declare const angular: any;
declare const language: any;

class ErrorDialogCtrl {
	/*@ngInject*/
	constructor(private $scope: ng.IScope, public $uibModalInstance: ng.ui.bootstrap.IModalServiceInstance, public header, public msg, public defaultStrings) {
		this.header = this.header || this.defaultStrings.error;
		this.msg = this.msg || this.defaultStrings.errorMessage;
	}

	close() {
		this.$uibModalInstance.close();
		this.$scope.$destroy();
	}
}

class MessageDialogCtrl {
	/*@ngInject*/
	constructor(private $scope: ng.IScope, public $uibModalInstance, public header, public msg, public defaultStrings) {
		this.header = this.header || this.defaultStrings.notification;
		this.msg = this.msg || this.defaultStrings.notificationMessage;
	}

	close() {
		this.$uibModalInstance.close();
		this.$scope.$destroy();
	}
}

class WaitDialogCtrl {
	public header: string;

	/*@ngInject*/
	constructor(
		private $scope: ng.IScope,
		private $uibModalInstance: ng.ui.bootstrap.IModalInstanceService,
		private $timeout: ng.ITimeoutService,
		public msg,
		public progress,
		public defaultStrings) {

		this.header = defaultStrings.pleaseWaitEllipsis;
		this.msg = this.msg || this.defaultStrings.processing;
		this.progress = this.progress || 0;

		//#Listeners
		//#Note: used $timeout instead of $scope.$apply() because I was getting a $$nextSibling error

		//#close wait dialog
		$scope.$on('dialogs.wait.complete', () => {
			this.$timeout(() => {
				this.$uibModalInstance.close();
				this.$scope.$destroy();
			});
		});

		//#update the dialog's message
		$scope.$on('dialogs.wait.message', (evt, args) => {
			this.msg = args.msg || this.msg;
		});

		//#update the dialog's progress (bar) and/or message
		$scope.$on('dialogs.wait.progress', (evt, args) => {
			this.msg = args.msg || this.msg;
			this.progress = args.progress || this.progress;
		});

		new InfiniteProgress((progress) => {
			this.progress = progress;
			$scope.$applyAsync();
		});
	}

	getProgress() {
		return {
			width: this.progress + "%"
		}
	}
}

class ConfirmDialogCtrl {
	/*@ngInject*/
	constructor(private $uibModalInstance: ng.ui.bootstrap.IModalInstanceService, public header, public msg, public defaultStrings) {
		this.header = this.header || this.defaultStrings.confirmation;
		this.msg = this.msg || this.defaultStrings.confirmationMessage;
	}

	no() {
		this.$uibModalInstance.dismiss("no");
	}

	yes() {
		this.$uibModalInstance.close("yes");
	}
}

export interface IFileDialogOptions {
	//разрешенные расширения файлов (массив)
	fileExts: string[];
	//для сабмита формы
	url: string;
	//дополнительный параметры передаваемые в querystring
	queryStringParams?: any;
	//дополнительные параметры для сабмита
	submitData?: any;
	//сообщение о разрешенных файловых расширений
	invalidFileExtMsg?: string;
	//максимальный размер файла, Кб
	maxFileSize?: number;
}

class FileUploadDialogCtrl<T> {
	public files: any[];
	public fileUploadService: FileUploadService<T>;

	/*@ngInject*/
	constructor(
		private $uibModalInstance,
		private options: IFileDialogOptions,
		public header,
		public defaultStrings
	) {
		this.header = this.header || "Загрузка файла";

		this.fileUploadService = new FileUploadService<T>(this.options.url, this.options.fileExts, { fileSizeLimit: this.options.maxFileSize });

		if (this.options.submitData) {
			this.fileUploadService.getSubmitData = () => this.options.submitData;
		}
	}

	upload() {
		this.fileUploadService.submit().then((uploadResult) => {
			this.$uibModalInstance.close(uploadResult);
		})
	}

	cancel() {
		this.$uibModalInstance.close();
	}
}

const asPromise = (modalInstance): Promise<any> => {
	return new Promise((resolve, reject) => {
		modalInstance.result.then((data) => resolve(data), (data) => reject(data));
	})
}

export interface WaitHandle {
	close();
}

export class DialogsService {
	/*@ngInject*/
	constructor(private $uibModal: ng.ui.bootstrap.IModalService) {
	}

	error(msg: string, header?: string, isStatic?: boolean): Promise<any> {

		const settings = {
			templateUrl: '/dialogs/error.html',
			controller: ErrorDialogCtrl,
			controllerAs: "ctrl",
			backdrop: isStatic ? 'static' : true,
			keyboard: isStatic ? false : true,
			resolve: {
				header: () => angular.copy(header),
				msg: () => angular.copy(msg)
			}
		}

		const modalInstance = this.$uibModal.open(settings);

		return asPromise(modalInstance);
	}

	wait(msg: string, progress?): WaitHandle {
		const settings = {
			templateUrl: '/dialogs/wait.html',
			controller: WaitDialogCtrl,
			controllerAs: "ctrl",
			backdrop: 'static',
			keyboard: false,
			resolve: {
				progress: () => angular.copy(progress),
				msg: () => angular.copy(msg)
			}
		}

		const modalInstance = this.$uibModal.open(settings);
		return {
			close: () => modalInstance.close()
		}
	}

	message(msg: string, header?: string, options?: any): Promise<any> {
		const defaultSettings = {
			templateUrl: '/dialogs/notify.html',
			controller: MessageDialogCtrl,
			controllerAs: "ctrl",
			backdrop: true,
			keyboard: true,
			resolve: {
				header: () => angular.copy(header || language.Generic.Common.kAttention),
				msg: () => angular.copy(msg)
			}
		}

		let settings = Object.assign({}, defaultSettings, options);
		const modalInstance = this.$uibModal.open(settings);

		return asPromise(modalInstance);
	}

	notify(header, msg, isStatic) {
		const settings = {
			templateUrl: '/dialogs/notify.html',
			controller: MessageDialogCtrl,
			controllerAs: "ctrl",
			backdrop: isStatic ? 'static' : true,
			keyboard: isStatic ? false : true,
			resolve: {
				header: () => angular.copy(header),
				msg: () => angular.copy(msg)
			}
		}

		const modalInstance = this.$uibModal.open(settings);

		return modalInstance.result;
	}

	confirm(msg: string, header?: string, isStatic?: boolean): Promise<any> {
		const settings = {
			templateUrl: '/dialogs/confirm.html',
			controller: ConfirmDialogCtrl,
			controllerAs: "ctrl",
			backdrop: isStatic ? 'static' : true,
			keyboard: isStatic ? false : true,
			resolve: {
				header: () => angular.copy(header),
				msg: () => angular.copy(msg)
			}
		}

		const modalInstance = this.$uibModal.open(settings);

		return asPromise(modalInstance);
	}

	confirmDelete(msg: string, header?: string, isStatic?: boolean): Promise<any> {
		const settings = {
			templateUrl: '/dialogs/confirmDelete.html',
			controller: ConfirmDialogCtrl,
			controllerAs: "ctrl",
			backdrop: isStatic ? 'static' : true,
			keyboard: isStatic ? false : true,
			resolve: {
				header: () => angular.copy(header),
				msg: () => angular.copy(msg)
			}
		}

		const modalInstance = this.$uibModal.open(settings);

		return asPromise(modalInstance);
	}

	uploadFile<T>(header: string, options: IFileDialogOptions, isStatic?: boolean): Promise<FileUploadResult<T>> {

		const settings = {
			templateUrl: '/dialogs/upload.html',
			controller: FileUploadDialogCtrl,
			controllerAs: "ctrl",
			backdrop: isStatic ? 'static' : true,
			keyboard: isStatic ? false : true,
			resolve: {
				header: () => angular.copy(header),
				options: () => options
			}
		}

		const modalInstance = this.$uibModal.open(settings);

		return asPromise(modalInstance);
	}

	create(url, ctrlr, data, opts) {
		opts = opts || {}
		const k = opts.keyboard || true
		const b = opts.backdrop || true
		const w = opts.windowClass || 'dialogs-default'

		const settings = {
			templateUrl: url,
			controller: ctrlr,
			backdrop: b,
			keyboard: k,
			windowClass: w,
			resolve: {
				data: () => angular.copy(data),
			}
		}

		const modalInstance = this.$uibModal.open(settings);

		return modalInstance.result;
	}

	translate(newStrings) {
		angular.extend(defaultStrings, newStrings);
	}
}

