class ShowerModalDialogService {
	private wait: WaitHandle = null;
	private counter: number = 0;

	/*@ngInject*/
	constructor(private $dialogs: DialogsService, private $timeout) {
	}

	show(message?: string, header?: string): WaitHandle {
		if (this.counter == 0 && !this.wait) {
			this.wait = this.$dialogs.wait(message || language.Generic.Common.kProcessing);
		}
		this.counter++;
		return {
			close: () => this.close()
		};
	}

	get isShowing() {
		return this.counter > 0;
	}

	close() {
		if (this.counter > 0) {
			this.counter--;
		}

		this.$timeout(() => {
			if (this.counter == 0 && this.wait) {
				this.wait.close();
				this.wait = null;
			}
		}, 100);
	}
}

export class LongWorkService extends ShowerModalDialogService {
	execute<T>(work: Promise<T> | ng.IPromise<T>, message?: string): Promise<T> {
		this.show();

		work.finally(() => {
			this.close();
		});

		return <Promise<T>>work;
	}
}

const InfiniteProgressBarComponent = {
	selector: "infiniteProgressBar",
	controller: class ProgressBarController {
		public progress: number;
		public percentComplete: string = " выполнено %";

		/*@ngInject*/
		constructor(private $scope: ng.IScope) {
		}

		$onInit() {
			new InfiniteProgress((progress) => {
				this.progress = progress;
				this.$scope.$applyAsync();
			});
		}

		public getProgress() {
			return {
				width: this.progress + "%"
			}
		}
	},
	controllerAs: "$ctrl",
	template: `<div class="progress progress-striped active">
					<div class="progress-bar progress-bar-info" ng-style="$ctrl.getProgress()"></div>
					<span class="sr-only">{{$ctrl.progress | number:2}}{{$ctrl.percentComplete}}</span>
				</div>`
}

class InfiniteProgress {
	private current: number = 0;
	private timer: any;

	constructor(
		private setCallBack: (progress: number) => void
	) {

		window.setTimeout(() => {
			this.timer = window.setInterval(() => {
				this.current = this.getNext();
				this.setCallBack(this.current);
			}, 100);
		}, 200);
	}

	getIncr(current: number) {

		if (current >= 1) {
			window.clearInterval(this.timer);
			return 0;
		}
		let rnd = 0;

		if (current >= 0 && current < 0.25)
			rnd = (Math.random() * (5 - 3 + 1) + 3) / 100		// Start out between 3 - 6% increments
		else if (current >= 0.25 && current < 0.65)
			rnd = (Math.random() * 3) / 100						// increment between 0 - 3%
		else if (current >= 0.65 && current < 0.9)
			rnd = Math.random() / 100							// increment between 0 - 1%
		else if (current >= 0.9 && current < 0.99)
			rnd = 0.001											// finally, increment it .1 %
		else {
			window.clearInterval(this.timer); // after 99%, don't increment:
			return 0;
		}

		return rnd;
	}

	getNext(): number {
		let incr = this.getIncr(this.current / 100) * 100 * 2;
		return this.current + incr;
	}

}

angular.module('uikit.dialogs.services', ['ui.bootstrap', 'ui.bootstrap.modal'])
