import { BaseRepository } from "./repository/baseRepository";
import { UnderscoreStatic } from "underscore";
import { SchoolyearDto } from "./models/common.model";
import { AppContext } from "./services/context";

declare var _: UnderscoreStatic;

export class ContextService extends BaseRepository {
	getContext() {
		return this.$http.get("/webapi/context")
			.then(this.handleResponse, this.handleError);
	}

	getYears(take?: number): Promise<SchoolyearDto[]> {
		let params: any = {};
		if (take) {
			params.take = take;
		}
		return this.$http.get("/webapi/context/years", { params: params })
			.then(this.handleResponse, this.handleError);
	}

	isYearTransitionState(appContext?: AppContext) : Promise<boolean> {
		return this.getYears(2)
			.then((years) => {
				const futureYear = years.find(y => y.closed == "Future");
				const openYear = years.find(y => y.closed == "Open");
				if (!futureYear) {
					return false;
				}
				return openYear.id == parseInt(appContext.yearId);
			});
	}
}


