/*@ngInject*/
const httpHtmlAntiCache = ($q, appContext: AppContext) => {
	return {
		request: (request) => {
			if (request.url.substr(-5) == '.html' && request.url.startsWith("/static/dist/")) {
				request.params = {
					ver: appContext.version
				}
			}
			return $q.resolve(request);
		}
	}
}

/*@ngInject*/
const configure = ($qProvider, loggerFactoryProvider: LoggerFactoryProvider, $uibModalProvider, $httpProvider: ng.IHttpProvider) => {
	$qProvider.errorOnUnhandledRejections(false);
	loggerFactoryProvider.config.enabled = window.appContext.environment != "prod";
	const modalHolder = $("#modals-holder");
	if (modalHolder.length) {
		$uibModalProvider.options.appendAfter = modalHolder;
	}
	$httpProvider.interceptors.push(httpHtmlAntiCache);
};

/*@ngInject*/
const run = ($http: ng.IHttpService, appContext: AppContext, router : Router) => {
	router.init()

	$http.defaults.withCredentials = true;
	$http.defaults.headers.common["at"] = appContext.at;
}

export class DownloadService {
	public downloadFile(url: string, options?: any): Promise<any> {
		return downloadFile(url, options);
	}

	public downloadAttachment(id: number, fileName: string): Promise<any> {
		return downloadFile("/webapi/attachments/" + id, fileName);
	}
}

export class NavigationService {
	/*@ngInject*/
	constructor(private pageContext: PageContext, private $location: ng.ILocationService) { }

	public navigateTo(url: string, data?: any, formPositionKey: string = "") {
		this.pageContext.checkForChanges().then(() => {
			let tabItem = this.pageContext.tabItem;
			this.pageContext.tabItem = null;
			if (formPositionKey) {
				saveFormPosition(formPositionKey, "/");
			}
			if (tabItem) {
				var auxInfo = { TabItem: tabItem };
				if (data) {
					angular.extend(data, auxInfo);
				} else {
					data = auxInfo;
				}
			}

			if (url.indexOf(".asp") > 0 || url.indexOf("/angular/") == 0) {
				postTo({ path: url, params: data });
			} else {
				this.$location.path(url).search({});
			}
		});
	}
}

const ContentPreloaderComponent = {
	controller: class ContentPreloader {
		constructor(public language: any) { }
	},
	controllerAs: "$ctrl",
	template: `<div class="content-preloader">
				<span class="arrows"></span>
				<span class="title">{{$ctrl.language.Generic.Curriculum.kPleaseWait}}</span>
			</div>`
}

angular.module("irtech.netcity.common", ["ui.bootstrap"])
	//.component("appComponent", AppComponent)
	.component("appMenu", MenuComponent)
	.component(FilterPanelComponent.selector, FilterPanelComponent)
	.component(RegistryComponent.selector, RegistryComponent)
	.directive("registryField", RegistryFieldDirective)
	.component("fileAttachments", FileAttachmentsComponent)
	.component(InputSuggestComponent.selector, InputSuggestComponent)
	.component("contentPreLoader", ContentPreloaderComponent)
	.service("router", Router)
	.service("dateUtils", DateUtils)
	.service("attachmentsRepository", AttachmentsRepository)
	.service("changeTracker", ChangeTracker)
	.service("taskQueueService", TaskQueueService)
	//.directive(Select2Directive.selector, Select2Directive)
	//.service("select2Stack", Select2StackService)
	//.value("select2Config", Select2Config)
	.factory("appContext", () => {
		//return AppInitializer.appContext || window.appContext;
		return window.appContext;
	})
	.factory("language", () => language)
	.service("baseRepository", BaseRepository)
	.service("settingsProvider", SettingsProvider)
	.service("contextService", ContextService)
	.service("pageContext", PageContext)
	.service("printExportService", PrintExportService)
	.provider("$appLoader", AppLoaderProvider)
	.provider("loggerFactory", LoggerFactoryProvider)
	.factory("downloadService", () => new DownloadService())
	.service("exceptionHandler", ExceptionHandler)
	.service("navigationService", NavigationService)
	//переопределение штатного angularjs обработчика ошибок
	.factory('$exceptionHandler', ['exceptionHandler', (exceptionHandler) => {
		return (exception, cause) => exceptionHandler.handleError(exception, cause);
	}])
	.directive("trackChanges", TrackChangesDirective)
	.directive("nsPanel", NsPanelDirective)
	.component(NsFormComponent.selector, NsFormComponent)
	.component(NsFormGroupComponent.selector, NsFormGroupComponent)
	.component(DateInputComponent.selector, DateInputComponent)
	.directive("fileUpload", FileUploadDirective)
	.directive("ngIndeterminate", IndeterminateDirective)
	.directive("tableRowHighlite", HighliteInputTableRowDirective)
	.directive("nsDateModel2", NsDateModel2Directive)
	.directive("nsDateInput", NsDateInputDirective)
	.filter("nsDate", NsDateFilter)
	.filter("nsDateTime", NsDateTimeFilter)
	.filter("nsDateTimeSs", NsDateTimeSsFilter)
	.filter("nsTime", NsTimeFilter)
	.filter("float2str", Float2Str)
	.controller("NetCityModalController", NetCityModalController)
	.controller("NetCityController", NetCityController)
	.config(configure)
	.run(run);

