"use strict";

import { BaseRepository } from "approot/global/repository/baseRepository";
import { NamedEntityDto, EnumItemDto } from "../models/common.model";

export class AddressRepository extends BaseRepository {
	getCities(ids){
		return this.$http.post("/webapi/addresses/cities", {ids})
			.then(this.handleResponse, this.handleError);
	}
	
	getProvinces(ids){
		return this.$http.post("/webapi/addresses/provinces", {ids})
			.then(this.handleResponse, this.handleError);
	}
}

export class EducOrganizationsRepository extends BaseRepository {
	getSchools(params, schoolIds){
		if(schoolIds && schoolIds.length){
			return this.$http.post("/webapi/schools/withLocationAndType", schoolIds, {params: params})
				.then(this.handleResponse, this.handleError);
		}

		return this.get("/webapi/schools/withLocationAndType", {params: params});
	}
}

export class ReferencesRepository extends BaseRepository {
	getTestLevels(){
		return this.$http.get("/webapi/references/testLevels")
			.then(this.handleResponse, this.handleError);
	}

	getTaskMistakeTypes(){
		return this.$http.get("/webapi/references/taskMistakeTypes")
			.then(this.handleResponse, this.handleError);
	}

	getTaskDifficults(){
		return this.$http.get("/webapi/references/taskDifficults")
			.then(this.handleResponse, this.handleError);
	}

	getProgramTypes() : Promise<NamedEntityDto[]>{
		return this.get("/webapi/references/addprogramtypes");
	}

	getProgramCosts() : Promise<EnumItemDto[]>{
		return this.get("/webapi/references/addprogramcosts");
	}

	getProgramEducForms() : Promise<NamedEntityDto[]>{
		return this.get("/webapi/references/addprogrameducforms");
	}

	getProgramStatuses() : Promise<NamedEntityDto[]>{
		return this.get("/webapi/references/addprogramstatuses");
	}
}



