import { Filter } from "./filter";
import { ListFilterSource, IFilterPanel, FilterModel } from "./filterpanel.model";
import { DialogsService } from "approot/global/providers/uikit.dialogs";

declare var language : any;

export class ChecksFilter extends Filter {
	private labelBlock: JQuery<HTMLElement>;

	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);

		let ctrl = this;

		let checkboxChanged = () => {
			if (this.status === 'inactive') {
				return;
			}
			if (this.model.hasSureCheckedFlag && this.control.find("input:checked").length == 0) {
				this.$dialogs.message(language.Generic.Filter.kSureCheckedMsg.replace('{0}', this.model.title));
				return false;
			}

			let checkboxValues = this.control.find('input:checked').map(function () { return $(this).prop('value'); }).get().join();
			return ctrl.setChoice(checkboxValues);
		};

		this.control = $("<div></div>").on("change", checkboxChanged);
	}

	setSource(src : ListFilterSource) {
		this.emptyChoice = false;
		this.control.empty();
		let itemsCount = src.items.length;

		if (itemsCount > 0) {
			this.setChecks(src.items);
			if (src.defaultValue) {
				return this.setChoice(src.defaultValue);
			}
		} else {
			if (this.model.emptyText) {
				this.labelBlock = $("<div></div>");
				this.labelBlock.append($("<input type=\"text\" class=\"form-control\" />").attr("disabled", "disabled").val(this.model.emptyText));
				this.labelBlock.appendTo(this.control);
				this.emptyChoice = true;
			}
			return this.setChoiceEnabling(false);
		}
	}

	getChoice() {
		return this.control.find('input:checked').map(function () { return $(this).prop('value'); }).get().join();
	}

	getChoiceText() {
		return this.control.find('input:checked').map(function () { return $(this).parent().text(); }).get().join();
	}

	setChoice(choice) {
		if (choice) {
			let checkedItems = choice.split(',');
			for (const item of checkedItems) {
				if (item || item === "0") {
					this.control.find('input:checkbox[value=' + item + ']').attr("checked", "");
				}
			}
		}
		return super.setChoice.call(this, choice);
	};

	setChecks(items) {
		let actualItems = items;
		for (const item of actualItems) {
			let chk = $("<input type=\"checkbox\" />").attr("name", this.model.id).val(item.value);
			if (item.readOnly) {
				chk.on("click", function () {
					return false;
				});
			}

			let lbl = $("<label></label>").text(item.title).prepend(chk);
			$("<div class=\"checkbox\"></div>").append(lbl).appendTo(this.control)
		}
	}

	enable() {

	}

	disable() {

	}

	validate() {
		let choice = this.getChoice();
		if (this.model.hasSureCheckedFlag && (choice === null || choice === "")) {
			this.$dialogs.error("Не выбраны значения фильтра \"" + this.model.title + "\"");
			return false;
		}
		return true;
	};
}

export class Checks2Filter extends ChecksFilter {

	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);
	}

	setChecks(items) {
		let actualItems = items;
		for (const item of actualItems) {
			let chk = $("<input type=\"checkbox\" />").attr("name", this.model.id).val(item.value);
			if (item.readOnly) {
				chk.on("click", function () {
					return false;
				});
			}

			let lbl = $("<label></label>").text(item.title).prepend(chk);
			$("<div class=\"checkbox checkbox-inline checkbox-row\"></div>").append(lbl).appendTo(this.control)
		}
	}
}




