import { AppContext } from "../services/context";
import { SetSelectedTab } from "webroot/static/src/common/js/common.menu";

class MenuItem {
	public title: string;
	public tabs: TabItem[];
	public submenu: MenuItem[];

	public dropDownMenu: boolean;
	public hasTabItems: boolean;
	public selected: boolean;

	constructor(dto : any) {
		this.title = dto.title
		this.tabs = dto.tabItemInfos.map((tabDto) => new TabItem(this, tabDto))
		this.submenu = dto.subMenus.map((subMenuDto) => new MenuItem(subMenuDto))
		this.dropDownMenu = dto.dropDownMenu
		this.hasTabItems = dto.hasTabItems
		this.selected = dto.selected
	}
}

class TabItem {
	public menuItem : MenuItem;
	public title: string;
	public id: number;
	public url: string;
	public selected: boolean;

	constructor(menuItem : MenuItem, dto) {
		this.menuItem = menuItem;

		this.title = dto.title
		this.selected = dto.selected
		this.id = dto.id
		this.url = dto.url
	}

	select() {
		this.selected = true
		this.menuItem.selected = true
	}


	unselect() {
		this.selected = false
		this.menuItem.selected = false
	}

}

class MenuComponentController {
	public menuCtx : any;

	constructor(appContext : AppContext) {
		this.menuCtx = (<any>appContext).menuContext;
		this.menuCtx.items = this.menuCtx.modelMenu.map(dto => new MenuItem(dto));
	}

	selectTab(tabItem) {
		SetSelectedTab(tabItem.id, tabItem.url);
	}
}

export const ActivateMenuItem = (href) => {
	const menu = $("ul.nav.navbar-nav");
	menu.find("li").removeClass("active");

	let hrefSearch = `a[href*="'${href}'"]`;

	if (href.slice(-1) === "/") {
		href = href.substr(0, href.length - 1);
		hrefSearch += "," + `a[href*="'${href}'"]`;
	}
	else {
		href += "/";
		hrefSearch += "," + `a[href*="'${href}'"]`;
	}

	let menuElem = menu.find(hrefSearch);

	menuElem.parent().addClass("active");
	menuElem.parents("li.dropdown").addClass("active");
	menuElem.closest(".navbar-inner").hide();
}

export const MenuComponent = {
	bindings: {},
	template: `
	<nav class="navbar-inner">
		<ul class="nav navbar-nav">
			<li ng-repeat-start="menuItem in $ctrl.menuCtx.items" class="dropdown" ng-class="menuItem.selected ? 'active' : ''" ng-if="menuItem.dropDownMenu">
				<a data-toggle="dropdown" href="#">
					{{menuItem.title}}
				</a>
				<ul class="dropdown-menu">
					<li class="divider" ng-if="!$first" ng-repeat-start="submenuItem in menuItem.submenu | filter:{ hasTabItems: true}"></li>
					<li class="dropdown-header">&nbsp;--&nbsp;{{submenuItem.title}}&nbsp;--&nbsp;</li>
					<li ng-repeat-end="" ng-repeat="tabItem in submenuItem.tabs" ng-class="tabItem.selected ? 'active' : ''">
						<a href="javascript:void(0)" ng-click="$ctrl.selectTab(tabItem)">{{tabItem.title}}</a>
					</li>
					<li ng-repeat="tabItem in menuItem.tabs" ng-class="tabItem.selected ? 'active' : ''">
						<a href="javascript:void(0)" ng-click="$ctrl.selectTab(tabItem)">{{tabItem.title}}</a>
					</li>
				</ul>
			</li>
			<li ng-repeat-end="" ng-repeat="tabItem in menuItem.tabs" ng-class="tabItem.selected ? 'active' : ''" ng-if="!menuItem.dropDownMenu && menuItem.hasTabItems">
				<a href="javascript:void(0)" ng-click="$ctrl.selectTab(tabItem)">{{tabItem.title}}</a>
			</li>
		</ul>
	</nav>`,
	controller: MenuComponentController
}



