import * as Modes from "approot/global/ui-components/tree/modes.js";

let modalWindowController = ($scope, $uibModalInstance, model) => {
    $scope.title = language.Generic.ServAdmin.kEOsBR;
    $scope.model = model;

    let buttonId = 0;
    let createButton = (text, handler, buttonclass, icon, disabled) => {
        return {
            id: buttonId++,
            class: buttonclass || 'btn-primary',
            action: handler,
            icon: icon,
            text: text,
            disabled: disabled ? disabled : () => false
        }
    }

    $scope.selected = $scope.model.selected;
    $scope.select = (selected) => {
        // Сохраняем результат полученный из контроллера выбора организаций
        $scope.selected = selected;
    }

    let switchToEditMode = () => {
        let updateMethod = $scope.model.settings.updateMethod;

        let newModel = typeof ($scope.model.settings.editModel) === "function"
            ? $scope.model.settings.editModel()
            : $scope.model.settings.editModel;

        newModel.settings = {
            mode: newModel.mode
        };

        $scope.model = newModel;
        okButton = () => {
            updateMethod($scope.selected);
            defaultOkButton();
        }

        $scope.buttons = getButtons($scope.model.settings.mode);
    }

    let defaultOkButton = () => $uibModalInstance.close($scope.selected)
    let okButton = defaultOkButton;

    let hasSelectedValue = (value) => {
        let result = false;
        let tree = $("#tree");
        if(tree && tree[0]) {
            tree.dynatree();
            tree.dynatree("getTree").getRoot().visit(n => {
                result = result || (n.bSelected == value);
            });
        }
        return result;
    }
    let select = (status) => $("#tree").dynatree("getTree").getRoot().visit(n => n.select(status));

    $scope.hasSelected = false;
    $scope.hasNotSelected = true;
    $scope.checkButtons = () => {
        $scope.hasSelected = !hasSelectedValue(true);
        $scope.hasNotSelected = !hasSelectedValue(false);
    }

    let getButtons = (mode) => {
        let buttons = [];
        if (Modes.checkMode(mode, Modes.switchToEdit)) {
            buttons.push(createButton(language.Generic.Buttons.kChoose, () => switchToEditMode(), 'btn-default pull-left', 'glyphicon-pencil'));
        }

        if (Modes.checkMode(mode, Modes.edit)) {
            buttons.push(createButton(language.Generic.Common.kCheckAll, () => {select(true);$scope.checkButtons()}, 'btn-default  pull-left', 'glyphicon-ok', () => {$scope.checkButtons(); return $scope.hasNotSelected}));
            buttons.push(createButton(language.Generic.Common.kUnCheckAll, () => {select(false);$scope.checkButtons()}, 'btn-default  pull-left', 'glyphicon-remove', () => {$scope.checkButtons(); return $scope.hasSelected}));

            buttons.push(createButton(language.Generic.Common.kOk, () => okButton(), 'btn-primary', 'glyphicon-ok'));
        }

        buttons.push(createButton(language.Generic.Common.kCancel_2, () => $uibModalInstance.dismiss('cancel'), 'btn-default', 'glyphicon-ban-circle'));
        return buttons;
    }

    $scope.buttons = getButtons(model.settings.mode);
}

const moduleNamespace = 'irtech.netcity.ui-components';
const moduleName = 'modalSelectOrganizations';

let modalWindowFactory = ($uibModal) => {
    return {
        selectOrgs: ({ mode = Modes.multi, functype = null, selected = null, order = null }) => {
            let modalWindowModel = {
                templateUrl: '/static/dist/app/global/ui-components/modalSelectOrganizations/template.html',
                controller: `${moduleName}Controller`,
                size: "lg",
                resolve: {
                    model: () => {
                        return {
                            selected: selected,
                            functype: functype,
                            settings: {
                                mode: mode | Modes.edit,
                                order: order,
                            }
                        }
                    }
                }
            }
            let instance = $uibModal.open(modalWindowModel);
            return instance.result;
        },
        showOrgs: ({ selected = [], updateMethod = null, editModel = null }) => {
            let switchToEditMode = editModel && Modes.switchToEdit || 0;

            let modalWindowModel = {
                templateUrl: '/static/dist/app/global/ui-components/modalSelectOrganizations/template.html',
                controller: `${moduleName}Controller`,
                size: "lg",
                resolve: {
                    model: () => {
                        return {
                            selected: selected,
                            functype: null,
                            settings: {
                                mode: Modes.read | switchToEditMode,
                                order: null,
                                editModel: editModel,
                                updateMethod: updateMethod
                            }
                        }
                    }
                }
            }
            let instance = $uibModal.open(modalWindowModel);
            return instance.result;
        }
    }
}

angular.module(moduleNamespace)
    .controller(`${moduleName}Controller`, modalWindowController)
    .factory(moduleName, modalWindowFactory)
    // Debug component
    .component('showModal', {
        controller: (modalSelectOrganizations) => {
            /*let model = {
                selected: [],
                //functype: 2,
                settings: {
                    mode: 2, // Modes.multi
                    //order: 2 // order by functype
                }
            }
            modalSelectOrganizations.open(model).then(response => console.log('modal windwo response', response));*/
            modalSelectOrganizations.showOrgs({}).then(response => console.log('modal windwo response', response));
            // modalSelectOrganizations.selectOrgs({}).then(response => console.log('modal windwo response', response));
        }
    });


