declare var dateUtils: any;

export const NsDateFilter = () => {
	return (dt: any) => {
		if (!dt) {
			return "";
		}
		let date: Date;
		if (typeof dt == "string") {
			date = new Date(dt);
		}
		else {
			date = dt;
		}
		return dateUtils.date2str(date);
	};
};

export const NsDateTimeFilter = () => {
	return (input) => {
		if (!input) {
			return "";
		}

		let date = new Date(input);
		let ddmmyyyy = dateUtils.date2str(date);

		let hours = date.getHours();
		let minutes = date.getMinutes();

		let hoursStr = (hours < 10) ? ('0' + hours) : hours;
		let minutesStr = (minutes < 10) ? ('0' + minutes) : minutes;
		let hhmm = `${hoursStr}:${minutesStr}`;
		let res = `${ddmmyyyy} ${hhmm}`;
		return res;
	}
}

export const NsDateTimeSsFilter = () => {
	return (input) => {
		if (!input) {
			return "";
		}

		let date: Date;
		if (typeof input == "string") {
			date = new Date(input);
		}
		else {
			date = input;
		}

		let ddmmyyyy = dateUtils.date2str(date);
		let hhmmss = dateUtils.time2Str_ss(date);

		let res = `${ddmmyyyy} ${hhmmss}`;
		return res;
	}
}

export const NsTimeFilter = () => {
	return (input) => {
		if (!input) {
			return "";
		}
		let date = new Date(input);
		return dateUtils.time2Str_ss(date);
	}
}

export const Float2Str = () => {
	return (input: any, arg1: any, arg2: string) => {
		if (typeof input === "undefined") {
			return "";
		}

		let returnValue = input || 0;
		if (arg1 && arg1 == "onlyPositive") {
			if (returnValue == 0 || returnValue == "0") {
				return "";
			}
		}
		
		let floatVal: number;
		if (typeof returnValue != "number") {
			floatVal = parseFloat(returnValue)
		}
		else {
			floatVal = returnValue;
		}

		if(input === 0){
			return "0";
		}

		let digits;
		if (arg1 && arg1 == "fractDigits") {
			digits = parseInt(arg2 || "2");
		}

		if(digits){
			returnValue = floatVal.toFixed(digits);	
		}
		else{
			returnValue = floatVal.toString();
		}
		
		returnValue = returnValue.replace('.', ',');

		return returnValue;
	}
}


