import { FilterPanelInfo, FilterSource, FilterValue, PreparedFilterPanelModel, FilterContext, IFilterPanel, IFilter, FilerPanelStyles, FilterStatus, FilterModel } from "./filterpanel.model";
import { DialogsService, LongWorkService } from "approot/global/providers/uikit.dialogs";
import { ListFilter, ListWithArrowsFilter, List2Filter } from "./list.filter";
import { Filter } from "./filter";
import { DateRangeFilter } from "./datetange.filter";
import { DateFilter } from "./date.filter";
import { UnderscoreStatic } from "underscore";
import { BaseRepository } from "approot/global/repository/baseRepository";
import { ListRangeFilter } from "./listrange.filter";
import { ChecksFilter, Checks2Filter } from "./checks.filter";
import { TextFilter } from "./text.filter";

declare var _: UnderscoreStatic;

enum FilterPanelStatus {
	init = "init",
	emptyChoice = "emptyChoice",
	ready = "ready"
};

export class FilterPanelRepository extends BaseRepository {
	getFpInfo(url: string): Promise<PreparedFilterPanelModel> {
		return this.$http.get(url)
			.then(this.handleResponse, this.handleError);
	}

	initFilters(url: string, ctx: FilterContext): Promise<FilterSource[]> {
		return this.$http.post(url, ctx)
			.then(this.handleResponse, this.handleError);
	}
}

export class FilterPanel implements IFilterPanel {
	private panel: JQuery<HTMLElement>;

	public filters: Filter[] = [];

	private handlers_ready: ((values: any) => void)[] = [];
	private handlers_init: (() => void)[] = [];
	private handlers_emptyChoice: ((emptyFilter: IFilter) => void)[] = [];

	public status: string;

	private template = '<div class="filters-panel form-horizontal"></div>';

	constructor(
		private $longWork: LongWorkService,
		private $dialogs: DialogsService,
		private filterPanelRepository: FilterPanelRepository,
		private container: JQuery<HTMLElement>,
		public model: FilterPanelInfo,
		public sources: FilterSource[],
		private initFiltersUrl: string,

		lazyInit?: boolean,
		private checkChanges?: () => Promise<void>,
		public filterSize?: FilerPanelStyles
	) {
		this.filterSize = this.filterSize || {};
		this.filterSize.label = this.filterSize.label || "control-label col-md-4 col-lg-3 col-sm-4";
		this.filterSize.control = this.filterSize.control || "col-md-8 col-lg-5 col-sm-8";

		if (this.container.hasClass("filters-panel")) {
			this.panel = this.container;
		} else {
			this.panel = $(this.template);
			this.container.append(this.panel);
		}
		if (!lazyInit) {
			this.initPanel();
		}
	}

	initPanel() {
		this.changeStatus(FilterPanelStatus.init);

		if (this.model === null) {
			this.$dialogs.error("Ошибка инициализации фильтр-панели. Модель не заполнена.");
			return;
		}

		this.model.filters = _.sortBy(this.model.filters, (item) => item.order);

		for (const filterModel of this.model.filters) {
			let active = true;
			let filterSource = this.sources.find(s => s.filterId == filterModel.id);
			if (!filterSource) {
				active = false;
			}

			let filterCtrl = this.buildFilter(filterModel);
			if (filterModel.dependencies) {
				let satisfied = filterCtrl.dependenciesSatisfied();
				if (!satisfied) {
					active = false;
				}
			}
			filterCtrl.appendToPanel(this.panel);
			if (filterSource) {
				filterCtrl.setSource(filterSource);
			}
			this.setFilterStatus(filterCtrl);
			this.filters.push(filterCtrl);
			if (!active) {
				filterCtrl.changeStatus(FilterStatus.inactive);
			}
		}

		this.panel.find(".form-group.aux").insertAfter(this.panel.find('.form-group:last-child'));
		return this.tryReady();
	}

	private buildFilter(filterModel: FilterModel): Filter {
		switch (filterModel.filterType) {
			case "List":
				return new ListFilter(this.$dialogs, this, filterModel);
			case "List2":
				return new List2Filter(this.$dialogs, this, filterModel);
			case "ListWithArrows":
				return new ListWithArrowsFilter(this.$dialogs, this, filterModel);
			case "DateRange":
				return new DateRangeFilter(this.$dialogs, this, filterModel);
			case "Date":
				return new DateFilter(this.$dialogs, this, filterModel);
			case "Checks2":
				return new Checks2Filter(this.$dialogs, this, filterModel);
			case "Checks":
				return new ChecksFilter(this.$dialogs, this, filterModel);
			case "ListRange":
				return new ListRangeFilter(this.$dialogs, this, filterModel);
			case "Text":
				return new TextFilter(this.$dialogs, this, filterModel);
			default:
				this.$dialogs.error("Ошибка инициализации фильтр-панели. Неподдерживаемый тип фильтра " + filterModel.filterType);
				return;
		}
	}

	private changeStatus(status: string) {
		console.log(status);

		this.panel.removeClass(this.status);
		this.status = status;
		this.panel.addClass(this.status);

		if (this.status === FilterPanelStatus.ready) {
			let fpValues = this.getValues();
			for (const handler of this.handlers_ready) {
				handler(fpValues);
			}
		}
		if (this.status === FilterPanelStatus.init) {
			for (const handler of this.handlers_init) {
				handler();
			}
		}
		if (this.status === FilterPanelStatus.emptyChoice) {
			let emptyChoiceFilter = this.filters.find((ft) => ft.getStatus() === FilterStatus.emptyChoice);
			for (const handler of this.handlers_emptyChoice) {
				handler(emptyChoiceFilter);
			}
		}
	}

	private tryReady() {
		if (!this.checkEmptyChoice()) {
			return this.changeStatus(FilterPanelStatus.ready);
		}
	}

	private setFilterStatus(filterCtrl: IFilter) {
		if (filterCtrl.emptyChoice) {
			if (filterCtrl.model.optionalFlag) {
				return filterCtrl.changeStatus(FilterStatus.inactive);
			} else {
				return filterCtrl.changeStatus(FilterStatus.emptyChoice);
			}
		} else {
			return filterCtrl.changeStatus(FilterStatus.active);
		}
	}

	getValues(excludeFilters?: IFilter[]): any {
		let activeFilters = this.filters.filter((ft) => ft.getStatus() === FilterStatus.active);

		if (excludeFilters) {
			activeFilters = activeFilters.filter(f => excludeFilters.findIndex(exf => exf.id === f.id) === -1);
		}

		let keyValues = activeFilters.map((x) => [x.id, x.getChoice()]);
		let values = _.object(keyValues);

		return values;
	}

	getCtxValues(excludeFilters?: IFilter[]): FilterValue[] {
		let activeFilters = this.filters.filter((ft) => ft.getStatus() === FilterStatus.active);

		if (excludeFilters) {
			activeFilters = activeFilters.filter(f => excludeFilters.findIndex(exf => exf.id === f.id) === -1);
		}

		return activeFilters.map((x) => ({
			filterId: x.id,
			filterValue: x.getChoice(),
			filterText: x.getChoiceText()
		}));
	}

	getTexts(forFilters?: string[]): any {
		let activeFilters = this.filters.filter((ft) => ft.getStatus() === FilterStatus.active);

		if (forFilters) {
			activeFilters = activeFilters.filter(ft => forFilters.indexOf(ft.id) > -1)
		}

		let keyValues = activeFilters.map((x) => [x.id, x.getChoiceText()]);
		let texts = _.object(keyValues);

		return texts;
	}

	checkChoiceEnabling() {
		return _.find(this.filters, function (ft) {
			return ft.getChoiceEnabling();
		});
	}

	checkEmptyChoice() {
		let emptyFilters = this.filters.filter((item) => item.getStatus() === FilterStatus.active || item.getStatus() === FilterStatus.emptyChoice);
		for (const emptyFilter of emptyFilters) {
			if (emptyFilter.emptyChoice && !emptyFilter.model.optionalFlag) {
				this.changeStatus(FilterPanelStatus.emptyChoice);
				return true;
			}
		}
		return false;
	}

	//перекрывается через настройки
	canChange(filter: IFilter, value: string, prevValue: string): Promise<boolean> {
		return Promise.resolve(true);
	}

	changedValue(filter: Filter, value: string, prevValue: string): void {
		console.log(filter.id + " = " + value);
		if (this.status === FilterPanelStatus.init) {
			return;
		}

		let preSendActionsPromise: Promise<void> = Promise.resolve();

		if (this.checkChanges) {
			preSendActionsPromise = this.checkChanges();
		}

		preSendActionsPromise
			.then(() => {

				this.changeStatus(FilterPanelStatus.init);
				let dependentFilters = filter.getDependency();

				let ctxValues = this.getCtxValues(dependentFilters);

				let ctx: FilterContext = {
					selectedData: ctxValues,
					params: null
				};

				const nextFilters: Filter[] = _.chain(this.filters)
					.sortBy((ft) => ft.model.order)
					.filter((ft) => ft.model.order > filter.model.order)
					.value() as unknown as Filter[];

				let existNextFilter = false;
				if (!nextFilters) {
					this.checkEmptyChoice();
				}

				for (const nextFilter of nextFilters) {
					if (!nextFilter.model.dependencies) {
						existNextFilter = true;
					}
					else if (nextFilter.dependenciesSatisfied()) {
						existNextFilter = true;
					}
					else {
						nextFilter.changeStatus(FilterStatus.inactive);
					}
				}

				if (!dependentFilters.length || !existNextFilter) {
					this.tryReady();
					if (filter.existStateProvider) {
						this.filterPanelRepository.initFilters(this.initFiltersUrl, ctx);
					}
					return;
				}

				this.$longWork.show();

				this.filterPanelRepository.initFilters(this.initFiltersUrl, ctx)
					.catch(() => {
						this.$longWork.close();
						this.changeStatus(FilterPanelStatus.emptyChoice);
						for (const dependFilter of dependentFilters) {
							dependFilter.changeStatus(FilterStatus.inactive)
						}
					})
					.then((filterSources: FilterSource[]) => {
						this.$longWork.close();
						for (const filterSrc of filterSources) {
							let filterCtrl = dependentFilters.find((ft) => ft.id === filterSrc.filterId && (!ft.model.dependencies || ft.dependenciesSatisfied()));
							if (!filterCtrl) {
								continue;
							}
							filterCtrl.setSource(filterSrc);
							this.setFilterStatus(filterCtrl);
						}

						for (const filterCtrl of nextFilters) {
							if (filterCtrl.model.dependencies) {
								let satisfied = filterCtrl.dependenciesSatisfied();
								if (!satisfied) {
									filterCtrl.changeStatus(FilterStatus.inactive);
								}
							}
						}

						this.tryReady();
					});
			})


	}

	validate() {
		let isValid = true;
		this.filters.forEach((filter) => {
			if (filter.getStatus() !== FilterStatus.active) {
				return;
			}
			if (!filter.validate) {
				return;
			}
			if (!filter.validate()) {
				isValid = false;
			}
		})
		return isValid;
	}

	ready(handler: (values: any) => void) {
		this.handlers_ready.push(handler);
	}

	init(handler: () => void) {
		this.handlers_init.push(handler);
	}

	emptyChoice = function (handler: (emptyFilter: IFilter) => void) {
		this.handlers_emptyChoice.push(handler);
	}
}





