import { DialogsService } from "../providers/uikit.dialogs";
import { SchoolyearDto, NamedEntityDto } from "../models/common.model";
declare var language : any;

export interface AppContext {
	at: string;
	readOnly : boolean;
	funcType: number;
	userLanguage: string;
	environment: string;
	version: string;

	rights: string[];
	roles: string[];

	userId: number;

	schoolId?: string;
	yearId?: string;
	currYear?: string;
	fullSchoolName?: string;
	productName: string;
	isTopEm: boolean;

	now: string;
	serverTimeZone: string;
	dateFormat: string;
	timeFormat: string;

	hasAnyRight: (checkRights: string[]|number[]) => boolean;
	hasRights: (checkRights: string[]|number[]) => boolean;
	hasRole: (checkRole: string|number) => boolean;

	//инициализируется в варианте без asp. см #27481
	schoolyear?: SchoolyearDto;
	organization?: NamedEntityDto;
}

export class PageContext {
	public title: string = "";
	public parent? : {
		title: string;
		href: string;
		postTo?: boolean;
	}
	public back? : {
		href?: string;
		history?: boolean;
	}
	private _tabItem: number = 0;

	public get tabItem(): number {
		return this._tabItem;
	}

	public set tabItem(newValue: number) {
		this._tabItem = newValue || 0;
		this.$document[0].forms["refreshfix"].TabItem.value = this._tabItem;
	}
	public leaveConfirmFunc: (callBack: any) => void;

	/*@ngInject*/
	constructor(
		public changeTracker, 
		private $q : ng.IQService, 
		private $dialogs: DialogsService,
		private $document: ng.IDocumentService) {
	}

	confirmAndLeave(leave){
		if (this.leaveConfirmFunc) {
			this.leaveConfirmFunc(leave);
			return;
		}
		this.checkForChanges().then(leave);
	};

	checkForChanges() : Promise<void>{
		return !this.changeTracker.isDataChanged() ? <Promise<void>>this.$q.when() : this.$dialogs.confirm(language.Generic.Common.kDataWereChanged);
	}
}



