import { Filter } from "./filter";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { IFilterPanel, FilterModel, FilterSource } from "./filterpanel.model";

export interface TextFilterSource extends FilterSource {
	validationExp?: string;
	validationErrorMessage?: string;
}

export class TextFilter extends Filter {

	private validationExp?: string;
	private validationErrorMessage?: string;

	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);

		let ctrl = this;
		this.validationExp = null;
		this.validationErrorMessage = null;
		this.control = $("<input></input>").addClass("form-control").attr("name", this.model.id).change(function () {
			return ctrl.setChoice($(this).val());
		});
	}

	setSource(src: TextFilterSource) {
		if (src.defaultValue) {
			this.setChoice(src.defaultValue);
		}

		this.validationExp = src.validationExp;
		this.validationErrorMessage = src.validationErrorMessage;

		super.setSource.call(this, src);
	}

	validate() {
		if (this.validationExp) {
			let choice = this.getChoice() as string;
			if (!choice.match(this.validationExp)) {
				this.$dialogs.error('Фильтр "' + this.model.title + '": ' + this.validationErrorMessage)
				return false;
			}
		}
		return true;
	};

	getChoice() {
		return $(this.control).val();
	}

	setChoice(choice) {
		$(this.control).val(choice);
		if (this.model.optionalFlag || choice) {
			this.emptyChoice = false;
		} else {
			this.emptyChoice = true;
		}
		super.setChoice.call(this, choice);
	}

	enable() {
		this.control.removeAttr("disabled");
	}

	disable() {
		this.control.attr("disabled", "disabled");
	}

}


