// Документация на dynatree http://wwwendt.de/tech/dynatree/doc/dynatree-doc.html
// Dynotree больше не поддерживается, документация мертва. Альтернативный источник документации http://web.archive.org/web/20181009203806/http://wwwendt.de:80/tech/dynatree/doc/dynatree-doc.html
// Документация на angular components
// * https://code.angularjs.org/1.6.4/docs/guide/component
// * https://code.angularjs.org/1.6.4/docs/tutorial/step_03
'use strict'
// Скрытие а не удаление отфильтрованных листьев
import * as Modes from "approot/global/ui-components/tree/modes.js";
import * as FuncTypes from "approot/global/references/funcTypes.js";

let treeController = ($scope, $element, $attrs) => {
    let $ctrl = $scope.$ctrl;

    $ctrl.$onInit = () => {
        // контроллер и привязки (bindings) инициализируются после исполнения функции
        $scope.$watch("$ctrl.model", $scope.rebuildTree);
        $scope.$watch("$ctrl.settings", () => {
            $scope.settings = angular.extend($scope.settings, $ctrl.settings);
            $scope.rebuildTree();
        });
    }

    $ctrl.selected = {};

    const defaultSettings = {
        mode: Modes.single | Modes.read,
        functype: FuncTypes.any,
        selected: {
            nodes: []
        },
    }

    $scope.settings = angular.extend({}, defaultSettings);

    // Элемент дерева
    $scope.tree = $('#tree', $element);
    let isTreeInited = false;
    $scope.rebuildTree = () => {
        // взять от дерева только листья
        let unpackNode = (node) => {
            if (node.childList) {
                return [node].concat(...node.childList.map(unpackNode));
            }
            return [node];
        }

        let readMode = {
            selectMode: 3,
            children: $ctrl.model,
            onExpand: (flag, node) => {
                let key = node.getKeyPath();
                if (flag) {
                    $scope.expandedList.push(key);
                } else {
                    $scope.expandedList = $scope.expandedList
                        .filter((nodeKey) => nodeKey != key);
                }
            }
        };

        let getSelectedModel = (selectedNodes) => {
            //let selectedNodes = $scope.tree.dynatree("getSelectedNodes").map(o => o.data);
            return {
                nodes: selectedNodes.filter(o => !o.isFolder)
            };
        }

        let editMode = {
            checkbox: Modes.checkMode($scope.settings.mode, Modes.multi),
            onSelect: (isSelected, node) => {
                let selectedNodes = $ctrl.selected.nodes || [];
                let nodes = unpackNode(node).map(node => node.data);

                if (isSelected) {
                    selectedNodes.push(...nodes)
                } else {
                    let keys = nodes.map(node => node.key);
                    selectedNodes = selectedNodes.filter((node) => keys.indexOf(node.key) < 0)
                }

                $ctrl.selected = getSelectedModel(selectedNodes.filter(o => !o.isFolder));
                // Передать выбранные верхнему контроллеру
                $ctrl.onUpdate({ selected: $ctrl.selected });
            },
            onActivate: (node) => {
                if (Modes.checkMode($scope.settings.mode, Modes.multi) || node.childList) return;

                let selectedNodes = [node.data];
                $ctrl.selected = getSelectedModel(selectedNodes);
                // Передать выбранные верхнему контроллеру
                $ctrl.onUpdate({ selected: $ctrl.selected });
            }
        };

        let configuredModel = !Modes.checkMode($scope.settings.mode, Modes.edit)
            ? readMode
            : angular.extend(readMode, editMode);

        $scope.dynatreemodel = angular.extend({}, $ctrl.dynatreemodel, configuredModel);

        $scope.tree.dynatree($scope.dynatreemodel);
        if (!isTreeInited) {
            saveExpanded();
            isTreeInited = true;
        }
        $scope.tree.dynatree("getTree").reload();

        let reselectNode = (node) => {
            if(!node.data.isFolder && selectedNodesIds.indexOf(node.data.id) >= 0)
                node.toggleSelect();
        }
        $ctrl.selected.nodes = ($ctrl.selected.nodes || []);
        let selectedNodesIds = $ctrl.selected.nodes.map(node => node.id);

        $scope.tree.dynatree("getRoot").visit((node) => {
            if (!node.isSelected()) {
                reselectNode(node);
                return;
            }
            let data = node.data;
            if (!data.isFolder) $ctrl.selected.nodes.push(data);
        });
        $ctrl.selected.nodes = _.uniq($ctrl.selected.nodes, false, 'id');
        $ctrl.onUpdate({ selected: getSelectedModel(($ctrl.selected.nodes || []).filter(o => !o.isFolder)) });

        loadeExpanded();
    };

    $scope.expandedList = [];
    let saveExpanded = () => {
        $scope.expandedList = [];
        $scope.tree.dynatree("getRoot").visit((node) => {
            if (node.isExpanded())
                $scope.expandedList.push(node.getKeyPath());
        });
    }

    let loadeExpanded = () => {
        $scope.tree.dynatree("getRoot").visit((node) => {
            if ($scope.expandedList.indexOf(node.getKeyPath()) < 0) return;
            node.expand(true);
        });
    }
}

let tree = {
    templateUrl: '/static/dist/app/global/ui-components/tree/template.html',
    controller: treeController,
    bindings: {
        settings: '<?',
        model: '=',
        onUpdate: '&'
    }
};

const moduleNamespace = 'irtech.netcity.ui-components';
const moduleName = 'tree';

angular.module(moduleNamespace)
    .component(moduleName, tree);


