
export interface ConnectionInfo {
	connection: any;
	queueHub: any;
}

export interface QueueExecutionOptions {
	getTaskFunc: () => Promise<number|EnqueueInfo>;
	header?: string;
	hint?: string;
	closeOnStart?: boolean;
	closeOnEnd?: boolean;
	logoutputMode?: boolean;
	userErrorHandler?: (message: string) => void;
	userCloseHandler?: () => void;
}

export interface ExecutionContext {
	taskId?: number;
	connectionInfo?: ConnectionInfo;
	error: boolean;
	progress: boolean;
}

export interface EnqueueInfo {
	taskId: number;
	activeConectionExec: boolean;
}

export interface TaskCompleteData {
	TaskId : number;
	Data: string
}

export interface TaskErrorData {
	TaskId : number;
	Details: string
}

export interface ProgressData {
	TaskId: number;
	Status: string
}

export enum TaskExecutionEvent {
	cancel = "cancel",
	complete = "complete",
	error = "error"
}

export const startingStatus = "Постановка в очередь обработки";


