// Режимы работы дерева
// Режимы работы дерева следует рассматривать как набор бинарнных флагов
/*
 нулевой бит -- режим редактирования (1 -- можно редактировать, 0 -- нельзя)
 первый бит -- режим выбора организацй (0 -- одна организация, 1 -- несколько организаций)
*/
export const read = 0;  // чтение (значение по умолчанию)
export const edit = 1; // редактирование 

export const single = 0; // выбор одной организации (значение по умолчанию)
export const multi = 2; // выбор нескольких организаций

export const switchToEdit = 4; // возможен переход к редактированию

// Проверка доступности режима
export const checkMode = (value, mode) => (value & mode) == mode;



