import { RegistryDescription, RegistryResponse, RegistryState, RegistryRequest, CommandExecutionResult } from "./registry.model";
import { BaseRepository } from "approot/global/repository/baseRepository";

export class RegistryRepository extends BaseRepository {
	getDescription(registryUrl: string): Promise<RegistryDescription> {
		return this.$http.get(registryUrl).then(this.handleResponse);
	}

	getState(registryUrl: string): Promise<RegistryState> {
		return this.$http.get(registryUrl + "/state").then(this.handleResponse);
	}

	getData(registryUrl: string, data: RegistryRequest): Promise<RegistryResponse> {
		return this.$http.post(registryUrl, data).then(this.handleResponse);
	}

	exportData(registryUrl: string, data: RegistryRequest): Promise<string> {
		return this.$http.post(registryUrl, data, { params: { export: true } }).then(this.handleResponse);
	}

	execCommand(registryUrl: string, commandId: string, data: any): Promise<CommandExecutionResult> {
		return this.$http.post(`${registryUrl}/command/${commandId}`, null, { params: data }).then(this.handleResponse);
	}
}


