export class PrintExportService {
	constructor($http, $timeout, $q, $compile, $rootScope) {
		this.http = $http;
		this.timeout = $timeout;
		this.q = $q;
		this.compile = $compile;
		this.rootScope = $rootScope;
	}

	loadTemplate(templPath) {
		let promise = this.http.get(templPath);
		return promise;
	}

	compileTemplate(template, model) {

		//копия скоупа
		var scope = this.rootScope.$new();

		var content = this.compile(template)(scope);

		scope = angular.extend(scope, model);

		var defer = this.q.defer();

		let self = this;

		this.timeout(function () {
			var wrappedContent = self.wrapContent(content);
			defer.resolve(wrappedContent);
		});

		return defer.promise;
	}

	//оборачивает в html->body
	wrapContent(content) {

		var html = $('<html />');
		var head = $('<head />');
		var body = $('<body />');

		content.appendTo(body);
		head.appendTo(html);
		body.appendTo(html);

		return html.wrap('<tag>').parent().html();
	};

	//создает новое окно браузера
	openNewWindow() {
		var defDiaryWinOpts =
		{
			name: "print_diary",
			specs: "status=no,toolbar=yes,menubar=yes,location=no,scrollbars=yes,resizable=yes,directories=no,width=790,height=590"
		};

		windowOpen(defDiaryWinOpts);

		return defDiaryWinOpts.winChild;
	};

	//печать
	print(templatePath, model) {

		this.loadTemplate(templatePath)
			.then((response) => {
				let template = response.data;
				let promise = this.compileTemplate(template, model);
				return promise;
			}).then((data) => {

				let printWindow = this.openNewWindow();
				var printDocument = printWindow.document;

				printDocument.open();
				printDocument.writeln(data);
				printDocument.title = appContext.productName;
				printDocument.close();

			}).catch((err) => {
				console.error(err);
			})
	}

	//экспорт в EXCEL
	export(templatePath, model, options) {

		this.loadTemplate(templatePath)
			.then((response) => {
				let template = response.data;
				let promise = this.compileTemplate(template, model);
				return promise;
			})
			.then((data) => {
				var content = $(data);
				let printUtils = content.printUtils();
				printUtils.toExcel(options);
			}).catch((err) => {
				console.error(err);
			});


	}
}

PrintExportService.$inject = ["$http", "$timeout", "$q", "$compile", "$rootScope"];


