declare var dateUtils: any;

export interface FilterPanelEvents {
	ready: (values: any) => void
	emptyChoice?: (emptyFilter: any) => void
	canChange?(filter: IFilter, value: string, prevValue: string): Promise<boolean>;
}

export enum FilterStatus {
	active = "active",
	inactive = "inactive",
	emptyChoice = "emptyChoice"
}

export interface FilerPanelStyles {
	compact?: boolean;
	label?: string;
	control?: string;
}

export interface FilterPanelSettings {
	url: string;
	initUrl?: string;
	info?: FilterPanelInfo;
	sources?: FilterSource[];
	events?: FilterPanelEvents;
	styles?: FilerPanelStyles;
	values? : any;
}

export interface FilterPanelInfo {
	filters: FilterModel[];
}

export interface PreparedFilterPanelModel {
	filterPanel: FilterPanelInfo;
	filterSources: FilterSource[];
}

export const statusActive = "active";
export const statusInactive = "inactive";

export interface FilterValue {
	filterId: string;
	filterValue: string;
	filterText: string;
}

export interface IFilterParam {
	name: string;
	value: string;
}

export interface FilterSource {
	filterId: string;
	defaultValue: string;
	nullText?: string;
	minValue?: string;
	maxValue?: string;
}

export interface FilterListItem {
	title: string;
	value: string;
}

export interface ListFilterSource extends FilterSource {
	items: FilterListItem[];
}

export interface FilterModel {
	id: string;
	title: string;
	filterType: string;
	emptyText: string;
	dependencies: FilterDependency[];
	existStateProvider: boolean;
	order: number;
	optionalFlag: boolean;
	hideSingleOption: boolean;

	nullOption: string;
	allOption: string;

	hasSureCheckedFlag: boolean;
}

export interface FilterDependency {
	relatedObject: RelatedObject;
	condition: string;
	relatedValue: string;
}

export interface RelatedObject {
	type: string;
	ref: string;
}

export interface FilterContext {
	selectedData: FilterValue[];
	params: IFilterParam[];
}

export interface IFilter {
	id: string;
	emptyChoice: boolean;
	choice: string;

	control: JQuery<HTMLElement>;
	status: string;
	choiceEnabling: boolean;
	existStateProvider: boolean;

	panel: IFilterPanel;
	model: FilterModel;

	getChoice(): string;
	getChoiceText(): string;

	setChoice(choice: string): void;

	setSource(source: FilterSource): void;

	getStatus(): FilterStatus;
	changeStatus(status: FilterStatus);

	getChoiceEnabling(): boolean;

	getDependency(): IFilter[];
	dependenciesSatisfied(): boolean;

	appendToPanel(panel: any);

	validate?(): boolean;
}

export interface IFilterPanel {
	model: FilterPanelInfo;

	sources: FilterSource[];
	filterSize?: any;

	filters: IFilter[];

	//текущий статус
	status: string;

	//первичная инициализация
	initPanel(): void;

	//валидаия
	validate(): boolean;

	//обработчик события отсутствия выбора
	emptyChoice(handler: (emptyFilter: any) => void): void;

	//обработчик события инициализации панели
	init(handler: () => void): void;

	//обработчик события готовности панели для выбора
	ready(handler: (values: any) => void): void;

	//обработчик изменений значений в фильтре
	changedValue(filter: IFilter, value: string, prevValue: string);

	//обработчик возможности изменения значения
	canChange(filter: IFilter, value: string, prevValue: string): Promise<boolean>;

	//получение текущих значений фильтра в виде объекта {<filterId>: <filterVal>}
	getValues(excludeFilters?: IFilter[]): any;

	//получение текущих значений фильтра в виде массива объектов [{filterId: <id>, filterValue: <val>}, ...]
	getCtxValues(excludeFilters?: IFilter[]): FilterValue[]

	//получение текущих подписей/текстовых представлений фильтров в виде объекта  {<filterId>: <filterText>}
	getTexts(forFilters?: string[]): any;
}

//класс описывающий диапазон дат
export class DateRange {
	constructor(public startDate: Date, public endDate: Date) {
		this.source = this.toString();
	}

	public source: string;

	public static parseDate(str: string): Date {
		let strDate = str.substring(0, 19);
		let date: Date;
		if (strDate.length == 19) {
			date = new Date(strDate);
		}
		else {
			date = dateUtils.str2date(strDate)
		}
		return date
	}

	public static parseRange(str: string): DateRange {
		let rangeArr = str.split(" - ");
		let startDate: Date;
		let endDate: Date;

		if (rangeArr[0])
			startDate = DateRange.parseDate(rangeArr[0])

		if (rangeArr[1])
			endDate = DateRange.parseDate(rangeArr[1])

		let range = new DateRange(startDate, endDate)
		range.source = str

		return range
	}

	//#представление диапазона в виде строки
	toString() {
		// #используем штатную сериализацию даты
		// #она приводит дату в utc формат
		// #соответственно в рамках контрола работа с датами проходит с часами: дата (+часовой пояс)
		let ret = ""
		if (this.startDate)
			ret += JSON.stringify(dateUtils.asUTCDate(this.startDate))
		ret += " - "
		if (this.endDate)
			ret += JSON.stringify(dateUtils.asUTCDate(this.endDate))

		return ret.replace(/"/g, "")
	}

	isValid() {
		return this.startDate <= this.endDate
	}
}


