const supplant = function(str, o) {
	return str.replace(
		/\{([^{}]*)\}/g,
		function (a, b) {
			var r = o[b];
			return typeof r === "string" || typeof r === "number" ? r : a;
		}
	);
};

const getFormattedTimestamp = function(date) {
	return supplant("{0}:{1}:{2}:{3}", [
		 date.getHours(),
		 date.getMinutes(),
		 date.getSeconds(),
		 date.getMilliseconds()
	]);
};

export class Logger {

	constructor($log, context, config){
		this.$log = $log;
		this.context = context;
		this.config = config;
	}

	_log(originalFn, args) {
		if (!this.config.enabled) {
			return;
		}
	
		var now = getFormattedTimestamp(new Date());
		var message = "", supplantData = [];
		switch (args.length) {
			case 1:
				message = supplant("{0} - {1}: {2}", [ now, this.context, args[0] ]);
				break;
			case 3:
				supplantData = args[2];
				message = supplant("{0} - {1}::{2}(\'{3}\')", [ now, this.context, args[0], args[1] ]);
				break;
			case 2:
				if (typeof args[1] === "string") {
					message = supplant("{0} - {1}::{2}(\'{3}\')", [ now, this.context, args[0], args[1] ]);
				} else {
					supplantData = args[1];
					message = supplant("{0} - {1}: {2}", [ now, this.context, args[0] ]);
				}
				break;
		}

		this.$log[originalFn].call(null, supplant(message, supplantData));
	}

	log() {
		this._log("log", arguments);
	}

	info() {
		this._log("info", arguments);
	}

	warn() {
		this._log("warn", arguments);
	}
	
	debug() {
		this._log("debug", arguments);
	}
	error() {
		this._log("error", arguments);
	}
}

export class LoggerFactory{
	constructor($log, config){
		this.$log = $log;
		this.config = config;
	}

	getInstance(context){
		return new Logger(this.$log, context, this.config);	
	}
}

export class LoggerFactoryProvider{
	constructor(){
		this.config = {
			enabled: false
		};
	}

	$get($log){
		return new LoggerFactory($log, this.config);
	}
}
LoggerFactoryProvider.prototype.$get.$inject = ["$log"];



