import { IFilterPanel, FilterModel, FilterSource, DateRange } from "./filterpanel.model";
import { Filter } from "./filter";
import { DialogsService } from "approot/global/providers/uikit.dialogs";

declare var dateInput : any;
declare var dateUtils: any;
declare var moment: any;
declare var language : any;

export class DateFilter extends Filter {

	private src : FilterSource;

	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);


		let baseName = this.model.id;

		let control = $("<input type=\"text\" class=\"input-md form-control filter-date\"/>").attr("name", baseName);
		let buttonCtrl = $("<button type=\"button\" class=\"btn btn-primary\">").append($("<span class=\"glyphicon glyphicon-calendar\"></span>")).append($("</button>"));
		let inputCtrl = $("<span class=\"input-group-btn\">").append(buttonCtrl).append($("</span>"));
		this.control = $("<div class=\"input-group date\">").append(control).append(inputCtrl).append($("</div>"));

		dateInput.initDateInput(this.control, null, null, null, {
			autoCorrectDates: false,
			keepEmptyField: true,
			autoclose: true
		}, true);

		let dateChanged = () => {
			var filterDate;
			if (this.status === 'inactive') {
				return;
			}
			filterDate = dateUtils.str2date(this.control.find('.filter-date').val());
			return this.setChoice(filterDate, true);
		}

		this.control.find('.filter-date').on("change", dateChanged);
	}

	setSource(src : FilterSource) {
		let minDate = moment(src.minValue).toDate();
		let maxDate = moment(src.maxValue).toDate();
		this.control.datepicker("setStartDate", minDate);
		this.control.datepicker("setEndDate", maxDate);

		let filterDate = moment(src.defaultValue).toDate();
		this.control.datepicker("setDate", filterDate);
		this.setChoice(filterDate, true);

		this.src = src;
	};

	setChoice(choice : string, internal? : boolean) {
		if (!choice) {
			super.setChoice(null);
			return;
		}
		//todo. выяснить что кроме строки сюда приходит
		if (this.choice && (<any>this.choice).source && (<any>this.choice).source === choice) {
			return;
		}
		if (!internal) {
			this.control.datepicker('update', choice);
		}
		let filterDate : Date = dateUtils.str2date(this.control.find('.filter-date').val());
		super.setChoice(filterDate);
	};


	validate() {
		if (this.choice === null || !this.choice) {
			this.$dialogs.error(language.Generic.Common.kErrInvalidDate);
			return false;
		}
		let minValue = dateUtils.asUTCDate(DateRange.parseDate(this.src.minValue));
		let maxValue = dateUtils.asUTCDate(DateRange.parseDate(this.src.maxValue));
		let filterDate = dateUtils.asUTCDate(<Date><unknown>this.choice);

		if (filterDate < minValue || filterDate > maxValue) {
			this.$dialogs.error(language.Generic.Common.kErrInvalidDate + '\n' + language.Generic.Common.kDateMustBeInCurrYear);
			return false;
		}
		return true;
	};

	enable() {
		return this.control.find("input").removeAttr("disabled");
	}

	disable() {
		return this.control.find("input").attr("disabled", "disabled");
	}

}


