import { FilterDependency } from "./filterpanel.model";
import { UnderscoreStatic } from "underscore";

declare var _: UnderscoreStatic;

export class DependencyTracker {
	constructor(private dependencies: FilterDependency[]) {
	}

	isSatisfied(vals: any) {
		let unSatisfiedDep = this.dependencies.find(dep => !this.checkDependency(vals, dep));
		return unSatisfiedDep == null;
	}

	public checkDependency(vals: any, dep: FilterDependency): boolean {

		let relObject = dep.relatedObject;
		if (relObject.type === "Param") {
			return true;
		}
		if (relObject.type !== "Filter") {
			throw "Неизвестный тип зависимости для фильтра"
		}
		let relFilterValue = vals[relObject.ref];
		if (typeof relFilterValue === 'undefined' || relFilterValue === null) {
			return false;
		}
		switch (dep.condition) {
			case "Equals":
				return relFilterValue === dep.relatedValue;
			case "Greater":
				return relFilterValue > dep.relatedValue;
			case "Less":
				return relFilterValue < dep.relatedValue;
			case "NotEquals":
				return relFilterValue !== dep.relatedValue;
			case "Any":
				return true;
			case "NotContains":
				return typeof relFilterValue === 'string' && relFilterValue.toString().indexOf(dep.relatedValue) < 0;
			case "Contains":
				return typeof relFilterValue === 'string' && relFilterValue.toString().indexOf(dep.relatedValue) >= 0;
			case "In":
				let arrValue = JSON.parse(dep.relatedValue);
				if (!Array.isArray(arrValue)) {
					return false;
				}
				return _.some(arrValue, function (v) {
					return v === relFilterValue;
				});
			default:
				return false;
		}
	}

}


