'use strict'

import * as FuncTypes from "approot/global/references/funcTypes.js";
import * as Repository from "approot/global/repository/repositories";
import * as Levels from "approot/global/ui-components/selectOrganizations/organizationTreeLevels.js";
import * as Modes from "approot/global/ui-components/tree/modes.js";

const groupBy = (elements, groupPropFunc) => {
    let result = {};
    let group = (element) => {
        let key = groupPropFunc(element);
        if (typeof (key) === 'object') {
            key = JSON.stringify(key);
        }
        if (result[key]) {
            result[key].push(element);
        } else {
            result[key] = [element];
        }
    }
    angular.forEach(elements, group);
    return result;
}

let copy = (array) => {
    let result = [];
    for (let i in array) {
        result.push(angular.extend({}, array[i]));
    }
    return result;
}

let isFirstInstance = (value, index, array) => array.indexOf(value) === index;

let selectOrganizationController = ($scope, $element, $attrs, educOrganizationsRepository, addressRepository, $q, modalSelectOrganizations) => {
    $scope.language = language;
    $scope.readMode = true;
    $scope.hasSelected = false;
    $scope.filter = '';
    let updateOrganizations = () => $scope.organizations = $scope.checkChildrens(angular.copy($scope.default));
    $scope.$watch("filter", updateOrganizations);
    $scope.default = [];
    $scope.$watch("default", updateOrganizations);

    let $ctrl = $scope.$ctrl;

    let getBranches = (selectedNodes) => {
        let result = [];

        let selectedIds = selectedNodes.map(o => o.id);
        let checkNode = (node) => {
            // Проверяем выбран ли листок
            if (!node.children) {
                return selectedIds.indexOf(node.id) != -1;
            }

            if (_.all(node.children, checkNode)) {
                result.push(node);
                return true;
            }
            return false;
        }

        $scope.default.map(checkNode);
        return result;
    }

    // Функция передачи выбранных на уровень выше
    $scope.onUpdate = (selected) => {
        // Подготовить информацию о полностью выбранных ветках
        let prepareBranch = (branch) => {
            let branchElement = branch.own[0];
            let result = {};
            if (branch.level <= Levels.functype)
                result['funcType'] = {
                    id: branchElement.funcTypeLevel.id,
                    name: branchElement.funcTypeLevel.name
                };
            if (branch.level <= Levels.city)
                result['city'] = {
                    id: branchElement.cityLevel.id,
                    name: branchElement.cityLevel.name,
                };
            if (branch.level <= Levels.province)
                result['municipalityDistrict'] = {
                    id: branchElement.provinceLevel.type == 'province'
                        ? branchElement.provinceLevel.id // Муниципальный район
                        : -branchElement.provinceLevel.id, // Городской округ
                    name: branchElement.provinceLevel.name
                }
            return result;
        }

        let result = {
            selectedIds: selected.nodes.map((node) => node.id),
            selectedOrgs: selected.nodes.map((node) => node.own[0]),
            selectedLevels: getBranches(selected.nodes).map(prepareBranch)
        };

        $scope.hasSelected = result.selectedIds.length > 0;
        // Передать результат верхнему контроллеру
        $ctrl.onUpdate({ selected: result });
    }

    // Настройки
    let getCompareFunction = () => {
        let order = ($ctrl.settings || $ctrl.model.settings || {}).order;
        // Если сортировка не указана, то неменяем порядок
        if (!order) return () => 0;

        switch (typeof (order)) {
            // Если задана сортировка, то исползуем её
            case 'function': return order;
            // Если указан уровень который должен быть вверху, то формируем функцию
            case 'number': return (a, b) => {
                if (a == b)
                    return 0;
                if (a == order)
                    return -1;
                if (b == order) {
                    return 1;
                }
                return 0;
            }
            // По умолчанию не меняем порядок
            default: return () => 0;
        }
    };

    $scope.$watch("$ctrl.model", () => {
        $ctrl.selected = null;
        $ctrl.settings = null;
        $ctrl.$onInit();
    });

    $ctrl.$onInit = () => {
        $ctrl.selected = $ctrl.selected || $ctrl.model.selected || [];
        $ctrl.settings = $ctrl.settings || $ctrl.model.settings || {};
        $scope.readMode = !Modes.checkMode($ctrl.settings.mode, Modes.edit);

        $scope.hasSelected = $ctrl.selected.length > 0;

        $scope.schoolsIds = $ctrl.selected.map(o => {
            if (typeof (o) === 'number')
                return o;
            if (typeof (o.id) === 'number')
                return o.id;
            return null;
        }).filter(o => !!o)

        // Получение организаций и мест расположения
        let params = {
            funcType: $ctrl.model.functype,
            //cityId: null,
            //districtId: null,
            //parentCityId: null
        };

        educOrganizationsRepository
            .getSchools(params, (Modes.checkMode($ctrl.settings.mode, Modes.edit)) ? null : $scope.schoolsIds)
            // Дополнение информации об организациях информацией о населённых пунктах и функциональностях
            .then((organizations) => {
                let group = (elements) => {
                    let result = {};
                    let group = (element) => {
                        let key = element.id;
                        result[key] = {
                            id: element.id,
                            name: element.name,
                            typeName: element.atoTypeName
                        };
                    }
                    angular.forEach(elements, group);
                    return result;
                }

                let provincesIds = organizations.map((o) => o.provinceId).filter(isFirstInstance).filter((o) => o);
                let provinces;
                let provincePromise = addressRepository.getProvinces(provincesIds).then((result) => provinces = group(result));

                let citiesIds = organizations.map((o) => o.cityId).filter(isFirstInstance);
                let parentsCitiesId = organizations.map((o) => o.parentCityId).filter(isFirstInstance);
                let cities;
                let cityPromise = addressRepository.getCities([...citiesIds, ...parentsCitiesId]).then((result) => cities = group(result));

                return $q.all([provincePromise, cityPromise]).then(() => {
                    return { organizations, provinces, cities }
                });
            })
            // Дополнение информацией о ветках
            .then((data) => {
                let organizations = data.organizations;
                let cities = data.cities;
                let provinces = data.provinces;

                // Дополняем модель названиями
                angular.forEach(organizations, (organization) => {
                    organization.funcTypeLevel = {
                        id: organization.funcType,
                        name: `${language.Generic.Common.kEOType} ${FuncTypes.locale[organization.funcType]}`,
                        type: "funcType"
                    };

                    organization.cityLevel = {
                        id: organization.cityId,
                        name: `${cities[organization.cityId].typeName || language.Generic.Common.kCity} ${cities[organization.cityId].name}`,
                        type: "city"
                    };

                    if (organization.provinceId && organization.parentCityId) {
                        console.error('conflict: province - parent city', organization);
                    }
                    if (organization.parentCityId) {
                        organization.provinceLevel = {
                            id: organization.parentCityId,
                            name: `${language.Generic.Common.kCityMunicipalityDistrict} ${cities[organization.parentCityId].name}`,
                            type: "city"
                        };
                    } else if (organization.provinceId) {
                        organization.provinceLevel = {
                            id: organization.provinceId,
                            name: `${language.Generic.Common.kProvince} ${provinces[organization.provinceId].name}`,
                            type: "province"
                        };
                    } else {
                        organization.provinceLevel = {
                            id: organization.cityId,
                            //name: provinces[organization.provinceId] || language.Generic.Common.kAll,
                            name: `${language.Generic.Common.kCityMunicipalityDistrict} ${cities[organization.cityId].name}`,
                            type: "city"
                        };

                        // Если можно в одиной ветке совместить тип образовательной организации и населённый пункт, то раскоментировать
                        //organization.cityLevel = null;
                    }

                    organization.type = "organization";
                });

                let compareFunction = getCompareFunction();
                let orderFunction = (a, b) => {
                    return compareFunction(a.level, b.level);
                };

                let treePropGetters = [
                    // сортировка дерева
                    //prop -- получение информации о ветке
                    //level -- уровень
                    { prop: (o) => o.provinceLevel, level: Levels.province },
                    { prop: (o) => o.cityLevel, level: Levels.city },
                    { prop: (o) => o.funcTypeLevel, level: Levels.functype },
                    { prop: (o) => o.name, level: Levels.educOrganization },
                ].sort(orderFunction);

                // Глубина раскрытия списка организаций
                const maxExpandDepth = 3;
                for (let index in treePropGetters) {
                    let getterObject = treePropGetters[index];
                    if (getterObject) {
                        getterObject.expand = index < maxExpandDepth
                    }
                }

                // Преобразование в дерево
                let organizationsList = mapBranch(organizations, treePropGetters.reverse());
                return organizationsList;
            })
            // Инициазлизация дерева
            .then((organizationsTree) => $scope.default = copy(organizationsTree));
    }

    // Преобразование линейного массива в ветку
    let mapBranch = (data, branchFuncs) => {
        let tuple = branchFuncs.pop();
        let func = tuple.prop;

        let getSubTree = (elements) => {
            let copyBranchFuncs = [];
            copyBranchFuncs.push(...branchFuncs);
            return mapBranch(elements, copyBranchFuncs);
        }

        let getBranch = (elements, keyString) => {
            let key = (tuple.level === Levels.educOrganization)
                ? elements[0]
                : JSON.parse(keyString);

            let result = {
                id: key.id,
                title: key.name,
                isFolder: !!branchFuncs.length,
                level: tuple.level,
                expand: tuple.expand,
                own: elements,
                key: `${tuple.level}-${key.type}-${key.id}`,
                children: (!!branchFuncs.length) ? getSubTree(elements) : null
            };

            if (result.isFolder) {
                result["children"] = getSubTree(elements);
            } else {
                result.select = $scope.schoolsIds.indexOf(result.id) >= 0;
            }

            return result;
        }

        let getBranchs = (group) => {
            let result = [];
            angular.forEach(group, (value, key) => result.push(getBranch(value, key)));
            return result;
        }

        let group = groupBy(data, func);
        let mainGroup = {};
        let nullGroup;
        angular.forEach(group, (value, key) => {
            if (key == 'null') {
                nullGroup = value;
            } else {
                mainGroup[key] = value;
            }
        })

        if (nullGroup) {
            return [...getBranchs(mainGroup), ...getSubTree(nullGroup)];
        } else {
            return getBranchs(mainGroup);
        }

    }

    // Фильтрация
    let filterFunc = (value, filterValues) => {
        let result = true;
        filterValues.forEach((filter) => result = result && (value.indexOf(filter) >= 0));
        return result;
    }

    $scope.checkChildren = (value) => {
        if (!value) {
            return false;
        }

        if (value.isFolder) {
            value.children = $scope.checkChildrens(value.children);
            return value.children.length > 0;
        }

        return filterFunc(value.title.toLowerCase(), $scope.filter.toLowerCase().split(' ')); // !(value.title.indexOf($scope.filter) < 0)
    }

    $scope.checkChildrens = (branch) => {
        if (!$scope.filter) return branch;
        return branch.filter($scope.checkChildren);
    }
}

let selectOrganizations = {
    templateUrl: '/static/dist/app/global/ui-components/selectOrganizations/template.html',
    controller: selectOrganizationController,
    bindings: {
        selected: '=?',
        settings: '<?',
        model: '=',
        onUpdate: '&'
    }
}

const moduleNamespace = 'irtech.netcity.ui-components';
const moduleName = 'selectOrganizations';

const module = angular.module(moduleNamespace);
module.component(moduleName, selectOrganizations);

module
    .factory("educOrganizationsRepository", ($http, $dialogs, $alerts) => new Repository.EducOrganizationsRepository($http, $dialogs, $alerts))
    .factory("addressRepository", ($http, $dialogs, $alerts) => new Repository.AddressRepository($http, $dialogs, $alerts))
    ;


