
class NsFormController {
	public labelSize: string;
	public controlSize: string;
}

export const NsFormComponent = {
	selector: 'nsForm',
	restrict: 'E',
	transclude: true,
	controller: NsFormController,
	template: "<ng-transclude></ng-transclude>",
	bindings: {
		labelSize: "@",
		controlSize: "@"
	}
}

class NsFormGroupController {
	public nsFormCtrl: NsFormController;

	public title: string;

	public fgLabelSize: string;
	public fgControlSize: string;

	public get labelSize(){
		return this.fgLabelSize || this.nsFormCtrl.labelSize;
	}

	public get controlSize(){
		return this.fgControlSize || this.nsFormCtrl.controlSize;
	}
}

export const NsFormGroupComponent = {
	restrict: 'E',
	selector: 'nsFormGroup',
	transclude: true,
	require: {
		nsFormCtrl  : "^^?nsForm"
	},
	controller: NsFormGroupController,
	controllerAs: "$fgCtrl",
	bindings: {
		fgLabelSize: "@labelSize",
		fgControlSize: "@controlSize",
		title: '@'
	},
	template: `
			<div class="form-group">
				<label class="control-label {{$fgCtrl.labelSize}}">{{$fgCtrl.title}}</label>
				<div class="{{$fgCtrl.controlSize}}">
					<ng-transclude></ng-transclude>
				</div>
			</div>
		`
}



