import { AppLoader } from "./apploader";
import { LoggerFactory, Logger } from "./logging";
import { ActivateMenuItem } from "./components/menu.component";
import { ChangeTracker } from "./changeTracker";
import { DialogsService } from "./providers/uikit.dialogs";

export class Router {
	private logger: Logger;
	private context: any;

	constructor(
		private $rootScope: ng.IRootScopeService,
		private $window: any,
		private $appLoader: AppLoader,
		private changeTracker: ChangeTracker,
		private $dialogs: DialogsService,
		private $location: ng.ILocationService,
		loggerFactory: LoggerFactory
	) {
		this.logger = loggerFactory.getInstance("router");
	}

	activateRouteMenu = (route: string) => {
		let appPart = this.context.app;
		let routePart = route;

		if (this.context.app === "school/userinfo") {
			//фикс для модуля ЛК пользователей.
			//актуально для всех модулей доступ к которым производится не из меню
			appPart = "school/users"
			routePart = route.substring(0, route.lastIndexOf('/'));
		}

		let hrefSearch = `/angular/${appPart}${routePart}`;
		ActivateMenuItem(hrefSearch);
	}


	updateSearch() {
		if (!document.forms["refreshfix"]) {
			return;
		}
		const searchData = this.$location.search();
		if (searchData && Object.getOwnPropertyNames(searchData).length) {
			document.forms["refreshfix"].search.value = JSON.stringify(searchData);
		} else {
			document.forms["refreshfix"].search.value = "";
		}
	};

	init() {
		//обработка маршрутизации
		this.$rootScope.$on("$routeChangeStart",
			() => {
				this.logger.debug("$routeChangeStart");
				this.$window.routeChanges = this.$window.routeChanges || 0;
				this.$window.routeChanges++;
				this.$appLoader.show();
			});


		this.$rootScope.$on("$routeChangeSuccess",
			() => {
				this.changeTracker.clearDataChanges();

				if (document.forms["refreshfix"]) {
					const baseUrl = document.forms["refreshfix"].baseurl.value;
					document.forms["refreshfix"].route.value = window.location.pathname.replace(`/angular/${baseUrl}`, "").replace(`/popup/${baseUrl}`, "");
				}

				let route = this.$location.path();
				this.activateRouteMenu(route);

				this.logger.debug("$routeChangeSuccess");

				if (this.$window.routeChanges > 1) {
					if (this.$window.appContext.yaCounters) {
						for (var counter of this.$window.appContext.yaCounters) {
							counter.hit(window.location.href);
						}
					}
				}
				this.updateSearch();
			});

		this.$rootScope.$on("$routeUpdate",
			() => {
				this.updateSearch();
				this.logger.debug("$routeUpdate");
			});

		this.$rootScope.$on("$routeChangeError",
			(event) => {
				this.logger.debug("$routeChangeError");
				this.$appLoader.hideArrows();
				if (this.$rootScope["test"]) {
					this.$appLoader.hideArrows();
				}
				this.$dialogs.error("Запрошенной страницы не существует").then(() => {
					this.$window.history.back();
				});
				event.preventDefault();
			});

		this.context = this.$window.context;

		if (this.context && (this.context.route !== "" && this.context.route !== "/" || this.context.search)) {
			this.logger.debug(`restoring current route ${this.context.route} from context`);

			this.activateRouteMenu(this.context.route);

			if (this.context.search) {
				this.$location.path(this.context.route).search(JSON.parse(this.context.search));
			} else {
				this.$location.path(this.context.route);
			}
		}
	}

}





