import { checkForChanges } from "./common.legacy.navigation";
import { openPopupWindow } from "./common.popup";

//глобальный scope
declare var appContext : any;
declare var window : any;

export const SetSelectedTab = (tbID: number, url: string) => {
	var form : HTMLFormElement = document.forms["MenuForm"];
	if (!form) {
		return;
	}

	var doNavigate = () => {
		if (tbID === 56) {
			url = (!url.match(/\/$/) ? url + "/" : url) + "?SchoolYearId=" + appContext.yearId + "&UserId=" + appContext.userId;
			openPopupWindow("_qualityAssessmentAnalytics", url, 950, 660);
			return;
		}
		if (tbID === 208) {
			url = `${!url.match(/\/$/) ? url + "/" : url}?EMId=${appContext.emId}&UserId=${appContext.userId}&GlobalYearId=${appContext.globalYearId}`
			openPopupWindow("_qualityAssessmentAnalyticsEM", url, 950, 660);
			return;
		}
		if (url.indexOf("window:") === 0) {
			let clearUrl = url.substring(7);
			let wndto = tbID === 66 ? "_staffAttest" : tbID;
			openPopupWindow(wndto, clearUrl, 1024, 800);
			return;
		}
		form.elements["TabItem"].value = tbID;
		form.action = url;
		window.isHaveToLogout = false;
		form.submit();
		return;
	};

	if (typeof window.AngularNavigateHandler === "function") {
		window.isHaveToLogout = false;
		window.AngularNavigateHandler(url).then(doNavigate, () => { });
		return true;
	}
	checkForChanges().then(doNavigate);
};

export const SetSelectedMenu = (miID : number, url: string) => {
	var form : HTMLFormElement = document.forms["MenuForm"];
	if (!form) {
		return;
	}
	checkForChanges().then(function () {
		form.elements["MenuItem"].value = miID;
		form.elements["TabItem"].value = 0;
		form.action = url;
		window.isHaveToLogout = false;
		return form.submit();
	});
	return false;
};


