export interface FileAttachmentsData {
	files: File[];
	context: any;
}

export interface FileAttachmentsOptions {
	multiple: boolean;
	showDescription: boolean;
	readonly?: boolean;
	filesExtensions?: string[];
	attachmentTypes?: NamedEntityDto[];
	onSuccessAttach?: (file: FileInfo) => void;
	onSuccessDetach?: (file: FileInfo) => void;
	uploadLimits?: UploadLimits;
}

export interface FileAttachmentsSettings {
	data: FileAttachmentsData;
	options: FileAttachmentsOptions;
}

export interface File {
	id: number;
	name: string;
	description: string;
	attachmentType?: number;
	//может ли быть удален из базы
	isCanDeleteFromDb?: boolean
}

export interface UploadLimits {
	fileSizeLimit: number;
}

export interface FileUploadResult<T> {
	result: T;
	fileName: string;
}

export interface FileInfo extends File {
	//привязан ли к сущности в базе
	isNew: boolean;
}

export class FileAttachments {
	public files: FileInfo[];

	constructor(private rawFiles: File[]) {
		this.files = this.files || [];
		this.rawFiles = this.rawFiles || [];
		this.mapFiles();
	}

	private mapFiles() {
		this.files = this.rawFiles.map((rawFile) => {
			return <FileInfo>{
				id: rawFile.id,
				name: rawFile.name,
				description: rawFile.description,
				attachmentType: rawFile.attachmentType,
				isNew: false,
				isCanDeleteFromDb: rawFile.isCanDeleteFromDb,
			}
		});
	}

	add(file: FileInfo) {
		this.files.push(file);
		this.files = this.files.sort((a, b) => {
			if (a.attachmentType > b.attachmentType) {
				return 1;
			}
			else if (a.attachmentType < b.attachmentType) {
				return -1;
			}
			else {
				if (a.name > b.name) {
					return 1;
				}
				else if (a.name < b.name) {
					return -1;
				}
				return 0;
			}
		});
	}

	removeById(ids: number | number[]) {
		if (Array.isArray(ids)) {
			this.files = this.files.filter((f) => ids.indexOf(f.id) === -1);
		}
		else {
			this.files = this.files.filter((f) => f.id !== ids);
		}
	}

	exist(): boolean {
		return !!this.files.length
	}

	current(): FileInfo {
		return this.files[0]
	}

	getById(id: number) {
		// if not id then return
		return this.files.find((f) => f.id === id);
	}
}

export class FileUploadService<T> {
	constructor(
		public uploadUrl: string,
		public extensions?: string[],
		public uploadLimits?: UploadLimits) {
	}

	public submit: () => Promise<FileUploadResult<T>>;
	public getSubmitData?: () => any;
	public onSuccess?: (data: FileUploadResult<T>) => any;
}

/*@ngInject*/
export const FileUploadDirective = <T>(appContext: AppContext, $dialogs: DialogsService, language: any, $longWork: LongWorkService) => {
	return {
		restrict: 'E',
		scope: {
			service: "="
		},
		template: `
			<div class="input-group">
				<span class="btn btn-primary btn-file input-group-addon">
					{{language.Generic.Common.kSelectFile}} <input type="file" name="fileAttachment">
				</span>
				<input type="text" class="form-control" disabled ng-value="filename" title="{{title}}" />
			</div>`,
		link: (scope, element) => {
			scope.language = language;
			let service = <FileUploadService<T>>scope.service;
			let fileInput = element.find("[name=fileAttachment]");

			fileInput.on('change', function () {
				let elements = this.value.split('\\');
				scope.filename = elements[elements.length - 1];
				scope.title = elements[elements.length - 1];
				scope.$applyAsync();
			});

			let submitPlugin = null;

			// привязывается событие, которое в момент сабмита добавляет дополнительные параметры, которые нужно передать на сервер 
			element.bind('fileuploadsubmit', (e, data) => {
				data.formData = {
					at: appContext.at
				};

				if (service.getSubmitData) {
					let extraData = service.getSubmitData();
					data.formData.data = encodeURIComponent(JSON.stringify(extraData));
				}
			});

			let promise = new Promise<FileUploadResult<T>>((resolve, reject) => {
				fileInput.fileupload({
					url: service.uploadUrl,
					dataType: 'json',
					add: (e, data) => {
						submitPlugin = data;
					},
					done: (e, data) => {
						if (!data.result) {
							$dialogs.error(language.Generic.Common.kUnexpErr);
							return;
						}

						let uploadResults: FileUploadResult<T> = {
							result: <T>data.result,
							fileName: scope.filename
						}

						if (service.onSuccess) {
							service.onSuccess(uploadResults);
						}

						resolve(uploadResults);
					},
					fail: (e, submit) => {
						let mappedresponse = {
							status: 500,
							statusText: "",
							data: {}
						}
						if (submit && submit.jqXHR && submit.jqXHR.status) {
							mappedresponse.status = submit.jqXHR.status;
							mappedresponse.statusText = submit.jqXHR.statusText;
						}
						if (submit.jqXHR.responseJSON) {
							mappedresponse.data = submit.jqXHR.responseJSON
						}
						new CommonXhrErrorHandler().handleErrorResponse(mappedresponse);
						reject(submit.jqXHR);
					},
					always: () => {
						$longWork.close();
					}
				});
			});

			service.submit = () => {
				if (submitPlugin == null || !scope.filename) {
					$dialogs.message('Необходимо выбрать файл');
					return;
				}

				let extensions = service.extensions;
				if (extensions && extensions.length) {
					let isExtensionsCorrect = extensions.some((ext) => scope.filename.toLowerCase().endsWith(ext));
					if (!isExtensionsCorrect) {
						$dialogs.message('Неверное расширение файла');
						return;
					}
				}

				if (service.uploadLimits) {
					//общие ограничения на загрузку
					if (submitPlugin.files[0].size && submitPlugin.files[0].size > service.uploadLimits.fileSizeLimit * 1024) {
						$dialogs.error(language.Generic.LearnApp.kServErrFileTooLarge + service.uploadLimits.fileSizeLimit / 1024 + ' Мб');
						return;
					}
				}

				// 	if not this.uploadLimits
				// 		jsSubmit({
				// 			action: '/webapi/attachments/uploadLimits'
				// 			method: 'GET'
				// 			auth: false
				// 			showProcessing: true
				// 			onSuccess: (uploadLimits) =>

				// 				this.uploadLimits = uploadLimits

				// 				fileSizeLimit = this.uploadLimits.fileSizeLimit
				// 				if this.params.context and this.params.context.PlanId
				// 					fileSizeLimit = this.uploadLimits.plannerDocFileNoteSizeLimit

				// 				if _datasubmit.files[0].size and _datasubmit.files[0].size > fileSizeLimit * 1024
				// 					return $.show.error(language.Generic.LearnApp.kServErrFileTooLarge + fileSizeLimit / 1024 + ' Мб')

				// 				$(document).trigger('showProcessing')
				// 				_datasubmit.submit()
				// 		})
				// 		return

				$longWork.show();
				submitPlugin.submit();

				return promise;
			}
		}
	}
}

class EditAttachmentController {
	public fileUploadService: FileUploadService<number>;

	public attachmentType?: NamedEntityDto;
	public header: string;

	public withTypes: boolean;

	public mode = {
		attach: false,
		edit: false
	}

	/*@ngInject*/
	constructor(
		private $uibModalInstance,
		private $alerts,
		private attachmentsRepository: AttachmentsRepository,
		private changeTracker: ChangeTracker,
		public language: any,
		public file: FileInfo,
		public withDescription: boolean,
		public fileExtensions?: string[],
		public uploadLimits?: UploadLimits,
		public context?: any,
		public attachmentTypes?: NamedEntityDto[]) {

		if (this.file.id) {
			this.mode.edit = true;
			this.header = language.Generic.Common.kEditAttachmentDescription;
			//todo. парсинг description

			// description = this.fileAttachments.getById(attachmentId).Description
			// if description && description.charAt(0) == '(' && description.indexOf(')')
			// 	type = description.substring(1).split(')')[0]
			// 	description = description.replace(/^ *\([^)]*\) */g, "")
		}
		else {
			this.header = language.Generic.Buttons.kAttachFile;
			this.mode.attach = true;

			const uploadService = new FileUploadService<number>('/webapi/attachments', this.fileExtensions, this.uploadLimits);

			uploadService.getSubmitData = () => {
				let extraData = Object.assign({}, this.context, {
					description: this.file.description,
					attachmentType: this.attachmentType && this.attachmentType.id
				});

				return extraData;
			};

			this.fileUploadService = uploadService;
		}

		this.withTypes = this.attachmentTypes && this.attachmentTypes.length > 0;

		if (this.file.attachmentType && this.attachmentTypes) {
			this.attachmentType = this.attachmentTypes.find((t) => t.id == this.file.attachmentType);
		}
	}

	attach() {
		this.fileUploadService.submit()
			.then(uploadResult => {
				let description = this.file.description;
				if (this.attachmentType) {
					description = "(" + this.attachmentType.name + ") " + description;
				}

				let file: FileInfo = {
					id: uploadResult.result,
					name: uploadResult.fileName,
					description: description,
					attachmentType: this.attachmentType && this.attachmentType.id,
					isNew: true
				}

				this.changeTracker.dataWasChanged();
				this.$alerts.success("Файл успешно загружен");
				this.$uibModalInstance.close(file);
			});
	}

	save() {
		this.attachmentsRepository.editDescription(this.file.id, this.file.description)
			.then(() => {
				this.$alerts.success("Описание успешно изменено");
				this.$uibModalInstance.close(this.file);
			});
	}

	cancel() {
		this.$uibModalInstance.dismiss("cancel")
	}
}

