export class AttachmentsRepository extends BaseRepository {
	delete(fileId: number, context?: any): Promise<any> {
		return this.$http.post('/webapi/attachments/' + fileId + "/delete", context)
			.then(this.handleResponse, this.handleError);
	}

	editDescription(fileId: number, description: string) {
		const postData = '=' + description;
		let options = { headers: { "Content-type": "application/x-www-form-urlencoded; charset=utf-8" } };

		return this.$http.post('/webapi/attachments/' + fileId + '/description', postData, options)
			.then(this.handleResponse, this.handleError);
	}
}

class FileAttachmentCtrl {
	public fileAttachments: FileAttachments;

	public settings: FileAttachmentsSettings;

	/*@ngInject*/
	constructor(
		public language: any,
		private $scope,
		private $dialogs: DialogsService,
		private attachmentsRepository: AttachmentsRepository,
		private downloadService: any,
		private $uibModal,
		private $alerts
	) {
	}

	$onInit() {
		if (this.settings && this.settings.data) {
			this.fileAttachments = new FileAttachments(this.settings.data.files || []);
		}
		this.$scope.$watch(() => this.settings && this.settings.data && this.settings.data.files, () => {
			if (this.settings && this.settings.data) {
				this.fileAttachments = new FileAttachments(this.settings.data.files || []);
			}
		});
	}

	openAttachment(file: FileInfo) {
		let downloadUrl = "/webapi/attachments/" + file.id + "/" + encodeURIComponent(file.name);
		this.downloadService.downloadFile(downloadUrl);
	}

	attachFile() {
		let file: FileInfo = {
			id: 0,
			name: "",
			description: "",
			isNew: true
		};

		var modalInstance = this.$uibModal.open({
			template: EditAttachmentComponent.template,
			controller: EditAttachmentComponent.controller,
			controllerAs: "$ctrl",
			resolve: {
				file: () => file,
				context: () => this.settings.data.context,
				fileExtensions: () => null,
				uploadLimits: () => this.settings.options.uploadLimits,
				withDescription: () => this.settings.options.showDescription,
				attachmentTypes: () => this.settings.options.attachmentTypes
			}
		});

		modalInstance.result.then((file: FileInfo) => {

			this.fileAttachments.add(file);
			this.settings.data.files = this.fileAttachments.files;

			if (this.settings.options.onSuccessAttach) {
				this.settings.options.onSuccessAttach(file);
			}

		});
	}

	editDescription(file: FileInfo) {
		var modalInstance = this.$uibModal.open({
			template: EditAttachmentComponent.template,
			controller: EditAttachmentComponent.controller,
			controllerAs: "$ctrl",
			resolve: {
				file: () => Object.assign({}, file),
				context: () => null,
				fileExtensions: () => null,
				uploadLimits: () => null,
				withDescription: () => this.settings.options.showDescription,
				attachmentTypes: () => this.settings.options.attachmentTypes
			}
		});

		modalInstance.result.then((editedFile: FileInfo) => {
			let file = this.fileAttachments.getById(editedFile.id);
			file.description = editedFile.description;
			this.settings.data.files = this.fileAttachments.files;

			this.$scope.$applyAsync();
		});
	}

	deleteFile(file: FileInfo) {
		if (typeof file.isCanDeleteFromDb !== "undefined" && !file.isCanDeleteFromDb) {
			this.fileAttachments.removeById(file.id);
			return
		}

		this.$dialogs.confirmDelete("Удалить файл " + file.name + "?").then(() => {
			//todo. процессинг
			this.attachmentsRepository.delete(file.id, this.settings.data.context)
				.then(() => {
					this.fileAttachments.removeById(file.id);
					this.settings.data.files = this.fileAttachments.files;

					if (this.settings.options.onSuccessDetach) {
						this.settings.options.onSuccessDetach(file);
					}
					this.$alerts.success("Файл успешно удален");
					this.$scope.$applyAsync();
				});
		});
	}
}

export const FileAttachmentsComponent = {
	controller: FileAttachmentCtrl,
	bindings: {
		settings: "=",
	},
	template: `
		<div class="file-attachment-block" ng-class="{'multiple': $ctrl.settings.options.multiple}">
			<div ng-repeat="file in $ctrl.fileAttachments.files" class="file-attachment" title="{{file.name + ' ' + file.description}}">
				<div class="file-info" ng-click="$ctrl.openAttachment(file);">
					<span class="file-name">{{file.name}}</span>
					<span class="file-description" ng-if="$ctrl.settings.options.showDescription && file.description">{{file.description}}</span>
				</div>
				<div id="{{file.id}}" class="buttons" ng-if="!$ctrl.settings.options.readonly">
					<span ng-click="$ctrl.editDescription(file)" ng-if="$ctrl.settings.options.showDescription" class="glyphicon glyphicon-pencil edit-description-button" aria-hidden="true" title="Редактировать описание"></span>
					<span ng-click="$ctrl.deleteFile(file)" class="glyphicon glyphicon-trash remove-button" aria-hidden="true" title="Удалить файл"></span>
				</div>
			</div>
			<button ng-if="!$ctrl.settings.options.readonly && ($ctrl.settings.options.multiple || !$ctrl.fileAttachments.files.length)" class="btn btn-default btn-sm" type="button" title="{{$ctrl.language.Generic.Buttons.kAttachFile}}" ng-click="$ctrl.attachFile()">
				<span class="glyphicon glyphicon-paperclip"></span> 
				{{$ctrl.language.Generic.Buttons.kAttachFile}}
			</button>
		</div>`
}



