"use strict";

import { CommonXhrErrorHandler } from "webroot/static/src/common/js/common.error.js";
import { DialogsService, LongWorkService } from "../providers/uikit.dialogs";

declare var window : any;

let staticInstance : BaseRepository = null;

export class BaseRepository {
	/*@ngInject*/
	constructor(protected $http, protected $dialogs : DialogsService, protected $longWork: LongWorkService) {
		staticInstance = this;
	}

	handleResponse(response) {
		$(document).trigger("closeProcessing");
		return response.data;
	}

	handleError(response) {
		if(staticInstance.$longWork){
			staticInstance.$longWork.close();
		}
		const errInformer = (message) => staticInstance.$dialogs.error(message);
		const messageInformer = (message) => staticInstance.$dialogs.message(message);
		return new CommonXhrErrorHandler(errInformer, messageInformer).handleErrorResponse(response);
	}

	get(url: string, options?: any) {
		if (window.appContext.environment === "dev") {
			console.log("url:", url);
			console.log("options:", options);
		}
		$(document).trigger("showProcessing");
		return this.$http.get(url, options).then(this.handleResponse, this.handleError);
	}

	post(url: string, options? : any) {
		if (window.appContext.environment === "dev") {
			console.log("url:", url);
			console.log("options:", options);
		}
		$(document).trigger("showProcessing");
		return this.$http.post(url, options).then(this.handleResponse, this.handleError);
	}
}


