export const NsPanelDirective = () => {
	return {
		restrict: 'E',
		transclude: true,
		scope: {
			panelId: "@",
			expanded: "<",
			class: "@",
			title: '@'
		},
		template: `
			<div class="panel panel-{{class}}">
				<div class="panel-heading" role="tab" id="heading{{panelId}}">
					<h4 class="panel-title">
						<a data-toggle="collapse" data-parent="#" ng-class="{'collapsed': !expanded}" data-target="#{{panelId}}" aria-expanded="{{expanded}}" aria-controls="{{panelId}}">
						{{title}}
						</a>
					</h4>
				</div>
				<div id="{{panelId}}" class="panel-collapse collapse" ng-class="{'in': expanded}" aria-labelledby="heading{{panelId}}" role="tabpanel">
					<div class="panel-body">
						<ng-transclude></ng-transclude>
					</div>
				</div>
			</div>
		`
	}
}




