import { Filter } from "./filter";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { IFilterPanel, FilterModel, FilterListItem, FilterSource } from "./filterpanel.model";

interface ListRangeSource extends FilterSource {
	itemsFrom: FilterListItem[]
	itemsTo: FilterListItem[]
}

export class ListRangeFilter extends Filter {
	public startControl: JQuery<HTMLElement>;
	public endControl: JQuery<HTMLElement>;
	public separatorCtrl: JQuery<HTMLElement>;

	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);

		let ctrl = this;
		this.control = $("<select></select>").addClass("form-control").attr("name", this.model.id)
			.change(function () {
				let value = $(this).val() as string;
				return ctrl.setChoice(value);
			});

		let baseName = this.model.id;
		this.startControl = $("<select></select>").addClass("form-control").attr("name", baseName + "_start").change(function () {
			return ctrl.setChoice($(this).val(), 1);
		});
		this.endControl = $("<select></select>").addClass("form-control").attr("name", baseName + "_end").change(function () {
			return ctrl.setChoice($(this).val(), 2);
		});
		this.separatorCtrl = $("<span class=\"input-group-addon\">-</span>");
		this.control = $("<div class=\"input-group\"></div>").append(this.startControl).append(this.separatorCtrl).append(this.endControl);
	}

	setSource(src: ListRangeSource) {
		this.emptyChoice = src.itemsFrom.length === 0;
		this.startControl.empty();

		let itemsCount = src.itemsFrom.length;
		if (itemsCount > 0) {
			this.setList(src.itemsFrom, this.startControl);
		}
		this.endControl.empty();
		itemsCount = src.itemsTo.length;
		if (itemsCount > 0) {
			this.setList(src.itemsTo, this.endControl);
		}

		if (src.defaultValue) {
			this.setChoice(src.defaultValue);
		}

		super.setSource(src);
	}

	setList(items: FilterListItem[], control: JQuery<HTMLElement>) {
		control.show();
		this.enable();

		for (const item of items) {
			let escapedHtml = (<any>(item.title)).escapeHTML();
			$("<option></option>").val(item.value).append(escapedHtml).appendTo(control)
		}
	}

	setChoice(choice: any, partNum?: number) {
		if (typeof partNum !== "undefined") {
			if (partNum === 1) {
				let endChoice = this.endControl.val();
				this.startControl.val(choice);
				if (choice && endChoice) {
					let choiceIndex = $(this.startControl).find("option[value='" + choice + "']").index();
					let endChoiceIndex = $(this.endControl).find("option[value='" + endChoice + "']").index();
					if (endChoiceIndex < choiceIndex) {
						this.endControl.val(choice);
					}
				}
			} else if (partNum === 2) {
				let startChoice = this.startControl.val();
				this.endControl.val(choice);
				if (choice && startChoice) {
					let choiceIndex = $(this.endControl).find("option[value='" + choice + "']").index();
					let startChoiceIndex = $(this.startControl).find("option[value='" + startChoice + "']").index();
					if (choiceIndex < startChoiceIndex) {
						this.startControl.val(choice);
					}
				}
			}
			choice = this.getChoice();
		} else {
			let sepIndex = choice.indexOf(" - ");
			if (sepIndex) {
				this.startControl.val(choice.substring(0, sepIndex));
				this.endControl.val(choice.substring(sepIndex + 3));
			}
		}
		super.setChoice(choice);
	}

	getChoice() {
		return this.startControl.val() + " - " + this.endControl.val();
	}

	enable() {
		return this.control.removeAttr("disabled");
	}

	disable() {
		return this.control.attr("disabled", "disabled");
	}
}


