"use strict";

let devDebug = (...args) => window.appContext.environment === "dev" && console.debug(...args);

let dateInputDirective = () => {
	let linkFunc = (scope, element, attr, controller) => {
		const setDate = (newDate) => {
			if (!newDate) return;
			newDate = dateUtils.str2date(newDate);
			if (!newDate) return;
			if (!scope.dateValue) {
				scope.dateValue = new Date();
				scope.dateValue.setMinutes(0);
			}
			scope.dateValue.setDate(newDate.getDate());
			scope.dateValue.setMonth(newDate.getMonth());
			scope.dateValue.setFullYear(newDate.getFullYear());
		}

		if(typeof(scope.dateValue) === "string"){
			let date = new Date(scope.dateValue);
			setDate(scope.dateValue);
			if(!scope.dateValue || typeof(scope.dateValue) === "string")
				scope.dateValue = date;
		}

		let initDateInput = () => window.dateInput.initDateInput($(".input-group.date", element), scope.minDate || null, scope.maxDate || null, null, { format: dateUtils.getDateFormat().format });
		scope.$watch(() => {
			if(scope.minDate) {
				initDateInput();
			}
			return scope.minDate;
		}, () => initDateInput());

		scope.$watch(() => {
			if(scope.maxDate) {
				initDateInput();
			}
			return scope.maxDate;
		}, () => initDateInput());
		initDateInput();

		scope.$watch("dateInputValue", setDate);

		let dateInputElement = $("#dateInput");
		scope.$watch(scope.dateValue, (value, valueold) => {
			if (scope.dateValue !== value && scope.dateValue !== valueold) {
				value = scope.dateValue;
			}

			if (!value) {
				dateInputElement.val("");
				return;
			}
			let val = dateUtils.date2str(value);
			scope.dateInputValue = val;
			dateInputElement.val(val);
		});
	}
	return {
		restrict: "E",
		require: "ngModel",
		replace: false,
		scope: {
			dateValue: "=ngModel",
			minDate: "=minDate",
			maxDate: "=maxDate",
		},
		link: linkFunc,
		templateUrl: "/static/dist/app/global/ui-components/dateinput/dateInputTemplate.html"
	}
}
angular
	.module("irtech.netcity.ui-components")
	.directive("dateInput", dateInputDirective)
;


