import { Filter } from "./filter";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { IFilterPanel, FilterModel, FilterSource, DateRange } from "./filterpanel.model";

declare var dateUtils: any;
declare var moment: any;
declare var language: any;
declare var dateInput: any;

export class DateRangeFilter extends Filter {
	private startDateIsChanged: boolean;
	private endDateIsChanged: boolean;

	private src: FilterSource;

	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);

		this.startDateIsChanged = false;
		this.endDateIsChanged = false;
		let baseName = this.model.id;
		let startControl = $("<input type=\"text\" class=\"input-md form-control start-date\"/>").attr("name", baseName + "_start");
		let endControl = $("<input type=\"text\" class=\"input-md form-control end-date\"/>").attr("name", baseName + "_end");
		let separatorCtrl = $("<span class=\"input-group-addon\">—</span>");
		this.control = $("<div class=\"input-daterange input-group date\"></div>").append(startControl).append(separatorCtrl).append(endControl);
		dateInput.initDateInput(this.control, "", "", "", {
			autoCorrectDates: false,
			keepEmptyField: true
		}, true);

		let dateChanged = () => {
			if (this.status === 'inactive') {
				return;
			}
			let startDate = this.control.find('.start-date').val();
			let endDate = this.control.find('.end-date').val();
			let range = !startDate && !endDate ? null : startDate + " - " + endDate;
			return this.setChoice(range, true);
		};

		let startDateBlur = () => {
			if (this.startDateIsChanged) {
				this.startDateIsChanged = false;
				let startDate = this.control.find('.start-date').val() as string;
				let endDate = this.control.find('.end-date').val() as string;
				if (startDate && endDate) {
					let dtStartDate = DateRange.parseDate(startDate);
					if (dtStartDate > DateRange.parseDate(endDate)) {
						if (this.validateDate(dtStartDate)) {
							this.control.find('.end-date').val(startDate);
						}
					}
				}
				return dateChanged();
			}
		};

		let endDateBlur = () => {
			if (this.endDateIsChanged) {
				this.endDateIsChanged = false;
				let startDate = this.control.find('.start-date').val() as string;
				let endDate = this.control.find('.end-date').val() as string;
				if (startDate && endDate) {
					let dtEndDate = DateRange.parseDate(endDate);
					if (dtEndDate < DateRange.parseDate(startDate)) {
						if (this.validateDate(dtEndDate)) {
							this.control.find('.start-date').val(endDate);
						}
					}
				}
				return dateChanged();
			}
		};

		let startDateChanged = () => {
			this.startDateIsChanged = true;
		};

		let endDateChanged = () => {
			this.endDateIsChanged = true;
		};

		let startDateChangedAndBlur = () => {
			if (!this.startDateIsChanged) {
				startDateChanged();
				return startDateBlur();
			}
		};

		let endDateChangedAndBlur = () => {
			if (!this.endDateIsChanged) {
				endDateChanged();
				return endDateBlur();
			}
		};

		this.control.find('.start-date').on("blur", startDateBlur);
		this.control.find('.end-date').on("blur", endDateBlur);
		this.control.find('.start-date').on("change", startDateChanged);
		this.control.find('.end-date').on("change", endDateChanged);
		this.control.find('.start-date').datepicker().on("changeDate", startDateChangedAndBlur);
		this.control.find('.end-date').datepicker().on("changeDate", endDateChangedAndBlur);

		super($dialogs, panel, model);

	}

	setSource(src) {
		let minDate: Date = moment(src.minValue).toDate();
		let maxDate: Date = moment(src.maxValue).toDate();
		this.control.find('.start-date, .end-date').datepicker("setStartDate", minDate);
		this.control.find('.start-date, .end-date').datepicker("setEndDate", maxDate);
		this.src = src;

		let range = new DateRange(minDate, maxDate);
		this.setChoice(range, true);
		return super.setSource.call(this, src);
	};

	getChoice() {
		let currChoice = this.choice;
		let currRange = new DateRange(currChoice.startDate, currChoice.endDate);
		return currRange.toString();
	};

	getChoiceText() {
		var currChoice;
		currChoice = this.choice;
		return moment(currChoice.startDate).format('DD.MM.YYYY') + " - " + moment(currChoice.endDate).format('DD.MM.YYYY');
	};

	setChoice(choice: string | DateRange, internal?: boolean) {
		if (!choice) {
			return;
		}

		let range = choice as DateRange;
		if (range && range.source) {
			if (this.choice && range.source === choice) {
				return;
			}
		}
		else {
			range = DateRange.parseRange(choice as string);
		}

		super.setChoice.call(this, range);
		if (internal) {
			return;
		}
		if (range.startDate) {
			this.control.find('.start-date').datepicker('update', dateUtils.date2str(range.startDate));
		}
		if (range.endDate) {
			this.control.find('.end-date').datepicker('update', dateUtils.date2str(range.endDate));
		}

		let startDate = this.control.find('.start-date').val();
		let endDate = this.control.find('.end-date').val();
		if (!startDate || !endDate) {
			let serializedRange = startDate + " - " + endDate;
			return this.setChoice(serializedRange, true);
		}
	};

	validateDate(dt) {
		var maxValue, minValue;
		minValue = dateUtils.asUTCDate(DateRange.parseDate(this.src.minValue));
		maxValue = dateUtils.asUTCDate(DateRange.parseDate(this.src.maxValue));
		return dt >= minValue && dt <= maxValue;
	};

	validate() {
		let range = this.choice as unknown as DateRange;

		if (range.startDate === null || !range.startDate) {
			this.$dialogs.error(language.Generic.Common.kErrInvalidStartDate);
			return false;
		}
		if (range.endDate === null || !range.endDate) {
			this.$dialogs.error(language.Generic.Common.kErrInvalidEndDate);
			return false;
		}

		let minValue = dateUtils.asUTCDate(DateRange.parseDate(this.src.minValue));
		let maxValue = dateUtils.asUTCDate(DateRange.parseDate(this.src.maxValue));

		let startDate = dateUtils.asUTCDate(new Date(range.startDate));
		let endDate = dateUtils.asUTCDate(new Date(range.endDate));
		if (startDate < minValue || startDate > maxValue) {
			this.$dialogs.error(language.Generic.Common.kErrInvalidStartDate + '\n' + language.Generic.Common.kStartEndDatesInCurrYear);
			return false;
		}
		if (endDate < minValue || endDate > maxValue) {
			this.$dialogs.error(language.Generic.Common.kErrInvalidEndDate + '\n' + language.Generic.Common.kStartEndDatesInCurrYear);
			return false;
		}
		if (!range.isValid()) {
			this.$dialogs.error(language.Generic.Common.kMsgStartBeforeEnd);
			return false;
		}
		return true;
	};

	enable() {
		return this.control.find("input").removeAttr("disabled");
	};

	disable() {
		return this.control.find("input").attr("disabled", "disabled");
	};
}


