import { Filter } from "./filter";
import { IFilterPanel, FilterModel, ListFilterSource, FilterListItem } from "./filterpanel.model";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { UnderscoreStatic } from "underscore";

declare var _: UnderscoreStatic;

const allOptionVal: string = "-1";
const nullOptionVal: string = "-2";

export class ListFilter extends Filter {
	constructor($dialogs: DialogsService, panel: IFilterPanel, model: FilterModel) {
		super($dialogs, panel, model);

		this.control = $("<select></select>").addClass("form-control").attr("name", this.model.id)
			.change(() => {
				let value = this.control.val() as string
				this.onChange(value);
			});
	}

	private sourceIds: string[];
	private labelBlock: JQuery<HTMLElement>;

	public setSource(src: ListFilterSource) {
		src.items = src.items || [];
		this.sourceIds = [];
		if (this.model.nullOption) {
			let nullItem = {
				title: this.model.nullOption,
				value: nullOptionVal
			};
			src.items.unshift(nullItem);
		}
		if (this.model.allOption) {
			this.sourceIds.unshift(allOptionVal);
		}

		this.sourceIds = this.sourceIds.concat(_.pluck(src.items, "value"));
		let itemsCount = src.items.length;
		this.emptyChoice = !itemsCount;
		this.control.empty();
		if (itemsCount > 0) {
			if (itemsCount === 1) {
				this.setChoiceEnabling(false);
				let item = src.items[0];
				this.setLabel(item.title, item.value);
				if (src.defaultValue) {
					src.defaultValue = item.value;
				}
				if (this.model.hideSingleOption) {
					this.filterRow.addClass("hidden");
				}
			} else {
				this.setList(src.items);
			}
		} else {
			this.setChoiceEnabling(false);
			this.setLabel(this.model.emptyText);
		}
		if (this.model.hideSingleOption && itemsCount !== 1) {
			this.filterRow.removeClass("hidden");
		}
		super.setSource(src);
	}

	setList(items: FilterListItem[]) {
		this.control.show();
		this.enable();
		if (this.labelBlock) {
			this.labelBlock.remove();
			this.labelBlock = null;
		}
		let actualItems = items;
		if (this.model.allOption) {
			actualItems.unshift({
				title: this.model.allOption,
				value: allOptionVal
			});
		}

		for (const item of actualItems) {
			let escapedTitle: string = (<any>item.title).escapeHTML();
			$("<option></option>").val(item.value).append(escapedTitle).appendTo(this.control);
		}
	}

	setLabel(title: string, value?: string) {
		this.control.hide();
		this.disable();
		if (this.labelBlock) {
			this.labelBlock.remove();
			this.labelBlock = null;
		}
		this.labelBlock = $("<div></div>");
		this.labelBlock.append($("<input type=\"text\" class=\"form-control\" />").attr("disabled", "disabled").val(title));
		if (value) {
			let valInput = $("<input type=\"hidden\" />").attr("name", this.model.id).val(value);
			this.labelBlock.append(valInput);
		}
		return this.labelBlock.insertAfter(this.control);
	}

	setChoice(choice: string) {
		if (!_.contains(this.sourceIds, choice)) {
			choice = _.first(this.sourceIds);
		}
		this.control.val(choice);
		super.setChoice(choice);
	}

	getChoiceText() {
		if (this.labelBlock) {
			return this.labelBlock.find('input[type=text]').val() as string;
		} else {
			return $("option:selected", this.control).text();
		}
	}

	enable() {
		if (this.labelBlock) {
			return this.labelBlock.find("input[type=hidden]").removeAttr("disabled");
		} else {
			return this.control.removeAttr("disabled");
		}
	};

	disable() {
		if (this.labelBlock) {
			return this.labelBlock.find("input[type=hidden]").attr("disabled", "disabled");
		} else {
			return this.control.attr("disabled", "disabled");
		}
	}

	protected onChange(value) {
		let prevValue = this.choice;
		this.panel.canChange(this, value, prevValue)
			.then((canChange) => {
				if (canChange) {
					this.setChoice(value);
				}
				else {
					$(this.control).val(prevValue);
				}
			})
	}
}

export class List2Filter extends ListFilter {
	private select2Control: any;

	setSource(src: ListFilterSource) {
		super.setSource(src);
		if (src.items.length > 1) {
			this.select2Control = this.control.select2({
				placeholder: "Введите наименование",
				language: "ru"
			});
		} else {
			this.control.select2();
			this.control.select2('close');
			this.control.siblings('span.select2').hide();
		}
	}
}

export class ListWithArrowsFilter extends ListFilter {
	appendToPanel(panel: JQuery<HTMLElement>) {
		let leftButton = $('<button type="button" class="btn btn-default"><span class="glyphicon glyphicon-circle-arrow-left"></span></button>')
			.click((event) => {
				let newValue = <string>$(event.target).closest(".input-group").find("select").find("option").filter(":selected").prev('option').val();
				this.onChange(newValue);
			});

		let rightButton = $('<button type="button" class="btn btn-default"><span class="glyphicon glyphicon-circle-arrow-right"></span></button>')
			.click((event) => {
				let newValue = <string>$(event.target).closest(".input-group").find("select").find("option").filter(":selected").next('option').val();
				this.onChange(newValue);
			});

		let buttonGroup = $('<span class="input-group-btn"></span>').append(leftButton).append(rightButton);

		$(this.control).addClass("list-with-arrows");
		let inputGroup = $('<div class="input-group"></div>')

		inputGroup.append(this.control);
		inputGroup.append(buttonGroup);

		this.filterRow.find("#filter-control").replaceWith(inputGroup);

		return panel.append(this.filterRow);
	}
}


