declare var angular : any;
declare var window : any;

import { ActivateMenuItem } from "../components/menu.component";
import { PageContext } from "../services/context.js";
import { ChangeTracker } from "../changeTracker.js";
import { DialogsService } from "../providers/uikit.dialogs.js";

export class NetCityController {
	/*@ngInject*/
	constructor($scope, $location : ng.ILocationService, $dialogs: DialogsService, $http: ng.IHttpService, $q : ng.IQService, changeTracker: ChangeTracker, pageContext: PageContext){
		$scope.page = pageContext;

		//здесь пока заглушки. 
		//заполнение пока ведется непосредственно в тех экранах где нужен данный контекст.
		//в последствии это должно загружаться вместе со всеми остальными данными (меню, текущая организация, и т.д.)
		$scope.context = {
			students: null,
			student: null
		};

		let cleanUrl = (url) => {
			return url.replace(/[/]?$/gm, "");
		}

		$scope.confirmAndLeave = (leave) => {
			if ($scope.page.leaveConfirmFunc) {
				$scope.page.leaveConfirmFunc(leave);
				return;
			}
			$scope.checkForChanges().then(leave);
		};

		$scope.checkForChanges = () => {
			return !changeTracker.isDataChanged() ? $q.when() : $dialogs.confirm(language.Generic.Common.kDataWereChanged);
		}

		$scope.changeYear = (yearId) => {
			$dialogs.wait(language.Generic.Curriculum.kPleaseWait);
			$http.post("/webapi/context/year", yearId).then(() => {
				window.postTo(window.location.pathname);
			});
		}

		const nowApp = $(document).find("base").attr("href");

		//навигация через меню (общее. используется перед базовой логикой ухода со страницы)
		window.AngularNavigateHandler = (url) => {

			if (url.indexOf(nowApp) === 0) {
				//навигация через меню (в рамках текущего модуля)

				const clearedRoute = `/${url.replace(nowApp, "")}`;

				if (cleanUrl($location.url()) !== cleanUrl(url)) {
					window.ChangeAngularRoute(clearedRoute, url);
				}

				//отклоняем базовую навигацию - редирект
				return Promise.reject();
			}

			//проверяем наличие изменений - выполням навигацию
			return new Promise((resolve, reject) => {
				$scope.confirmAndLeave(resolve);
			});
		}

		
		window.ChangeAngularRoute = (url, full) => {
			if (!url.endsWith("/") && url.indexOf("?") === -1) {
				url += "/";
			}

			$scope.confirmAndLeave(() => {
				$location.path(url);
				if (!$scope.$$phase) {
					$scope.$apply();
				}
				ActivateMenuItem(full);
			});
		}

		window.ShowHelp = () => {
			let helpPage = window.location.pathname.replace("/angular/", "");

			helpPage = helpPage.replace(/[0-9]|\//g, "_").split("_").filter(function(item) { return item !== "" }).join("_");

			helpPage = `/help/${helpPage}.htm`;

			if ($scope.page.help) {
				helpPage = $scope.page.help;
			}

			window.openPopupWindow("_help", helpPage, 950, 660);
		}
	}
}


