"use strict";

class Controller {
	constructor() {
		this.br = '<br />';
	}

	init() {
		this.sourceModelValue = angular.copy(this.model.value);
	}

	validate(validator) {
		let condition = new RegExp(validator.condition);
		let value = validator.sourceValue ? this.sourceModelValue : this.model.value;
		return condition.test(value == undefined ? "" : value);
	}

	getInformationClass(info){
		return `alert-${info.type.toLowerCase()}`;
	}

	getType() {
		const predefined = ['Select', 'Date', 'CheckBox'];

		if(predefined.indexOf(this.model.type) >= 0){
			return this.model.type;
		}

		return 'Input';
	}

	getDefaultValue(model) {
		if(typeof(model.value) === "boolean") {
			return this.model.value.toString();
		}

		if(typeof(model.value) === 'number') {
			return this.model.value.toString();
		}

		return model.value || this.mapEnumKey(Object.keys(model['availableValues'])[0]);
	}

	mapEnumKey(value) {
		if(typeof(value) == "boolean" || value == "true" || value == "false") return value;
		return value && `${value[0].toUpperCase()}${value.slice(1)}`;
	}

	isDisabled() {
		let result = this.isEdit && !(this.isEditable() || this.model.isEditable);
		return !this.prepareEmbendedScripts(!result);
	}

	getValueBySystemName(model, systemName){
		let field = model.find(o => o.systemName == systemName);
		return field && field.value;
	}

	prepareEmbendedScripts(previewValue){
		const replacer = (str) => str.replace(/(this\.parentModel)\.(\w+)/gm, "this.getValueBySystemName($1, '$2')");

		let lastResult = previewValue;
		for(let index in this.model.embendedScriptsEditable){
			let embendedScript = this.model.embendedScriptsEditable[index];
			switch(embendedScript.combinationWithOtherOperations){
				case 'And':
					if(!lastResult) continue;
					lastResult = eval(replacer(embendedScript.script));
				break;

				case 'Or':
					if(lastResult) continue;
					lastResult = eval(replacer(embendedScript.script));
				break;
			}
		}
		return lastResult;
	}

	isEditable() {
		return this.model.isEditableInStatus.indexOf(this.status) >= 0;
	}
}

const controllerName = "EditModelFieldController";

let component = {
	templateUrl: "/static/dist/app/global/ui-components/codebaseView/field/editModelFieldTemplate.html",
	controller: controllerName,
	controllerAs: "$ctrl",
	bindings: {
		model: "=ngModel",
		isEdit: "=isEdit",
		status: "=status",

		parentModel: "=",

		minDate: "=",
		maxDate: "=",
	}
}

const moduleNamespace = 'irtech.netcity.ui-components';
const moduleName = 'uiEditField';

angular.module(moduleNamespace)
	.controller(controllerName, Controller)
	.component(moduleName, component);


