import { BehaviorSubject, Subject } from "approot/global/models/common.reactive";
import { startingStatus, EnqueueInfo, TaskExecutionEvent } from "./taskqueue.model";

class TaskExecutionController {
	public message: string;

	public activeConectionExec: boolean = false;
	public inProgress = true;

	public logoutput: { time: Date, message: string }[];

	/*@ngInject*/
	constructor(
		$scope: ng.IScope,
		private $uibModalInstance: ng.ui.bootstrap.IModalInstanceService,
		public language: any,

		private statusSubject: BehaviorSubject<string>,
		taskEnqueueInfoSubject: BehaviorSubject<EnqueueInfo | Number>,
		private eventsSubject: Subject<TaskExecutionEvent>,

		public logoutputMode: boolean,
		public hint: string,
		public header?: string
	) {
		this.header = this.header || "Подождите";

		if (logoutputMode) {
			this.logoutput = [];
		}

		statusSubject.subscribe((status) => {
			if (logoutputMode) {
				this.logoutput.unshift({ time: new Date(), message: status });
			}
			else {
				this.message = status;
			}
			$scope.$applyAsync();
		})

		taskEnqueueInfoSubject.subscribe((enqueueInfo) => {
			if (typeof (enqueueInfo) !== "number") {
				this.activeConectionExec = (<EnqueueInfo>enqueueInfo).activeConectionExec;
			}
		});

		eventsSubject.subscribe((event) => {
			if (event === TaskExecutionEvent.complete || event === TaskExecutionEvent.error) {
				this.inProgress = false;
			}
		})
	}

	public taskInitialized(): boolean {
		return this.statusSubject.getValue() !== startingStatus;
	}

	public close() {
		this.$uibModalInstance.close();
	}

	public cancel() {
		this.eventsSubject.next(TaskExecutionEvent.cancel);
		this.$uibModalInstance.close();
	}
}

export const TaskExecutionComponent = {
	controller: TaskExecutionController,
	controllerAs: "$ctrl",
	templateUrl: "/static/dist/app/global/services/queue/taskexecution.component.html"
}


