import { ChangeTracker } from "../changeTracker";

class InputSuggestController {
	public title: string;
	public model: string;
	public suggestions: string[];

	/*@ngInject*/
	constructor(private changeTracker: ChangeTracker) {
	}

	use(item: string) {
		this.model = item;
		// todo: вызов без контекста, может дальше и понадобится
		this.changeTracker.dataWasChanged();
	}
}

export const InputSuggestComponent = {
	controller: InputSuggestController,
	selector: "inputSuggest",
	bindings: {
		model: "=",
		title: "<",
		suggestions: "<",
	},
	template: `
	<div class="input-group copyto">
		<input type="text" ng-model="$ctrl.model" class="form-control" />
		<div class="input-group-btn">
			<button type="button" class="btn btn-default dropdown-toggle" data-toggle="dropdown" aria-expanded="false">
				<span>{{$ctrl.title}}</span>
				<span class="caret"></span>
			</button>
			<ul class="dropdown-menu dropdown-menu-right">
				<li ng-repeat="item in $ctrl.suggestions">
					<a href="javascript:void(0);" ng-click="$ctrl.use(item)">{{item}}</a>
				</li>
			</ul>
		</div>
	</div>`
}


